-- =============================================================================
-- 502 — LE CAHIER D'EXERCICES DE 2DE (partie 4)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/2de/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 502 --niveau 2de --fichiers anglais.n3,anglais.n4,arts-plastiques.n1,emc.n1 --suffixe 4 > supabase/contenu/502_exercices_2de_4.sql
--
-- 90 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   anglais.n3              30 exercices · 10 chapitres
--   anglais.n4              21 exercices · 7 chapitres
--   arts-plastiques.n1       9 exercices · 3 chapitres
--   emc.n1                  30 exercices · 10 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('b14995b7-4d6a-5eaa-8cd0-71ba94a53e56'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les souvenirs de Gran","competence":"comprendre-langue","situation":"Ben envoie une photo de sa grand-mère au bord de la mer. Elle lui raconte comment elle vivait autrefois. Repère comment elle parle de ses anciennes habitudes.","documents":[{"id":"gran","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Ben","emoji":"👦","cote":"gauche"},{"nom":"Gran","emoji":"👵","cote":"droite"}],"repliques":[{"qui":"Ben","texte":"Gran, you look so relaxed in this photo!"},{"qui":"Gran","texte":"I used to live in a noisy flat. Now I live by the sea."},{"qui":"Gran","texte":"Every morning I would take the 7.15 train to work. Now I walk on the beach with my dog."},{"qui":"Ben","texte":"It sounds so different!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les deux mots qui montrent que Gran ne vit plus dans un appartement bruyant.","aide":"Cherche la structure qui parle d’un état passé, aujourd’hui terminé.","type":"zone","document":"gran","multiple":true},{"enonce":"Touche le mot qui annonce une action répétée tous les matins dans le passé.","aide":"Il sert à raconter une habitude passée, surtout dans un récit.","type":"zone","document":"gran","multiple":false},{"enonce":"Complète la négation.","aide":"À la forme négative, avec *didn’t*, la structure perd son -d.","type":"trous","segments":["Gran didn’t ",0," live by the sea when she was young."],"banque":["used","using","uses","use"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9","m10"]},"explication":"**used to** + base verbale exprime un état ou une habitude passés et révolus : Gran a vécu dans un appartement bruyant, mais ce n’est plus le cas."},{"cle":{"type":"zone","ids":["m25"]},"explication":"**would** + base verbale exprime une habitude passée répétée : chaque matin, Gran prenait le train."},{"cle":{"type":"trous","trous":[["use"]]},"affichage":"use","explication":"À la négation, on écrit **didn’t use to** : *didn’t* porte déjà le prétérit, donc *use* perd son -d."}]$ex$::jsonb),
  ('b14995b7-4d6a-5eaa-8cd0-71ba94a53e56'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Maya, hier et aujourd’hui","competence":"manier-langue","situation":"Maya a déménagé de Leeds à Bath. Sa vie a changé : son tableau compare les habitudes de ses dix ans et celles d’aujourd’hui.","documents":[{"id":"maya","type":"tableau","titre":"Maya’s life","colonnes":["","When Maya was ten","Today"],"lignes":[["Home","a flat in Leeds","a house in Bath"],["Saturday","play football","go swimming"],["School run","walk with her dad","take the bus"],["August","visit her gran by the sea","work in a café"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche la case qui dit comment Maya va à l’école aujourd’hui.","aide":"Cherche la ligne « School run » et la colonne « Today ».","type":"zone","document":"maya","multiple":false},{"enonce":"Écris une phrase sur le logement de Maya quand elle avait dix ans. Le premier mot est « Maya ».","aide":"Il s’agit d’un état passé révolu : la structure est *used to* + base verbale.","type":"ordre","items":[{"id":"a","texte":"a"},{"id":"b","texte":"in"},{"id":"c","texte":"live"},{"id":"d","texte":"to"},{"id":"e","texte":"flat"},{"id":"f","texte":"Maya"},{"id":"g","texte":"used"}]},{"enonce":"Quelle phrase NE PEUT PAS se dire avec « would » ?","aide":"*Would* accepte des actions répétées, pas des états. Quel verbe est un état ?","type":"choix","options":[{"id":"a","texte":"Maya would play football every Saturday."},{"id":"b","texte":"Maya would walk to school with her dad."},{"id":"c","texte":"Maya would live in a flat in Leeds."},{"id":"d","texte":"Maya would visit her gran every August."}],"multiple":false},{"enonce":"Relie chaque phrase à ce qu’elle exprime.","aide":"Repère le *be used to*, qui parle d’un état actuel, et le présent simple avec *usually*.","type":"association","gauche":[{"id":"g0","texte":"I used to live in Leeds."},{"id":"g1","texte":"I’m used to the rain."},{"id":"g2","texte":"We would visit Gran every August."},{"id":"g3","texte":"I usually walk to school."}],"droite":[{"id":"d0","texte":"Habitude présente"},{"id":"d1","texte":"J’y suis habitué"},{"id":"d2","texte":"Habitude passée répétée, dans un récit"},{"id":"d3","texte":"Autrefois oui, plus maintenant"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c2"]},"explication":"Aujourd’hui, Maya **takes the bus** : c’est une habitude présente, qui se dit au présent simple."},{"cle":{"type":"ordre","ids":["f","g","d","c","b","a","e"]},"explication":"**Maya used to live in a flat** : *used to* + base verbale pour un état passé qui n’existe plus."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Maya would live in a flat** est impossible : *live* décrit ici un état, et *would* refuse les états. Pour un état passé, seul *used to* convient."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g2":"d2","g0":"d3"}},"explication":"**used to** : révolu ; **be used to** : habitué ; **would** : habitude répétée du récit ; présent simple + *usually* : habitude présente."}]$ex$::jsonb),
  ('b14995b7-4d6a-5eaa-8cd0-71ba94a53e56'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un nouveau départ à Glasgow","competence":"manier-langue","situation":"Sam vient de déménager de Cardiff à Glasgow pour un nouveau travail. Il écrit à son amie Aisha et a noté son emploi du temps avant et après.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Sam’s email","blocs":["Dear Aisha,","Glasgow is great! In Cardiff I used to cycle to work, but here I take the underground. At first I wasn’t used to the crowds, but now I’m getting used to them. I’m also used to getting up early, because the office opens at seven. My neighbour says I’ll soon be used to living in the rain!","See you soon, Sam"],"source":"Courriel écrit pour l’exercice"},{"id":"emploi","type":"tableau","titre":"Sam’s routine","colonnes":["","Cardiff","Glasgow"],"lignes":[["Work","cycle","underground"],["Wake-up","7.30","6.00"],["Weather","dry","rainy"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux verbes en -ING qui suivent « be used to ».","aide":"Dans *be used to*, *to* est une préposition : le verbe qui suit prend -ING.","type":"zone","document":"lettre","multiple":true},{"enonce":"D’après la lettre et le tableau, quelle phrase est exacte ?","aide":"Regarde la ligne « Work » : que faisait Sam à Cardiff, et que fait-il à Glasgow ?","type":"choix","options":[{"id":"a","texte":"Sam is getting used to cycling to work in Glasgow."},{"id":"b","texte":"Sam is used to cycle to work, and he still does it."},{"id":"c","texte":"Sam used to cycle to work, but now he takes the underground."},{"id":"d","texte":"Sam used to take the underground, but now he cycles."}],"multiple":false},{"enonce":"Complète d’après la ligne « Wake-up ».","aide":"*Be used to* est suivi d’un verbe en -ING.","type":"trous","segments":["Sam used to get up at 7.30. Now he’s used to ",0," up at six."],"banque":["getting","get","gets","got"]},{"enonce":"Range chaque phrase selon ce qu’elle exprime.","aide":"Cherche *used to* + base verbale, *be used to* + -ING, ou un simple présent avec *every day* / *often*.","type":"categories","categories":[{"id":"c0","texte":"Passé révolu (used to)"},{"id":"c1","texte":"Habitué (be used to + -ING)"},{"id":"c2","texte":"Habitude présente"}],"items":[{"id":"i0","texte":"I used to cycle to work."},{"id":"i1","texte":"She’s used to working late."},{"id":"i2","texte":"I’m used to getting up at six."},{"id":"i3","texte":"I take the underground every day."},{"id":"i4","texte":"We often walk to the station."},{"id":"i5","texte":"He used to live in Cardiff."}]},{"enonce":"Combien d’heures plus tôt Sam se lève-t-il à Glasgow qu’à Cardiff ?","aide":"Compare 7.30 et 6.00 : de 6.00 à 7.30, il y a une heure et demie.","type":"nombre","unite":"h"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m38","m55"]},"explication":"**getting** et **living** : après *be used to*, *used* est un adjectif et *to* une préposition, donc le verbe se met en -ING."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Sam used to cycle to work, but now he takes the underground** : *used to* exprime une habitude passée terminée ; le tableau confirme le changement."},{"cle":{"type":"trous","trous":[["getting"]]},"affichage":"getting","explication":"**getting** : après *be used to*, on emploie le verbe en -ING (*he’s used to getting up*)."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c2","i4":"c2","i5":"c0"}},"explication":"*Used to* + base verbale : passé révolu ; *be used to* + -ING : habitué ; présent simple + adverbe : habitude présente."},{"cle":{"type":"nombre","valeur":1.5,"tolerance":0},"affichage":"1,5 h","explication":"De 6.00 à 7.30, il y a **1,5 h** (1 h 30)."}]$ex$::jsonb),
  ('bd47bfd3-6bc0-5c8d-b855-b6963b1ec465'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les règles du camp Willow","competence":"comprendre-langue","situation":"Lena est en colonie de vacances au camp Willow. L’affiche du camp explique ce que le directeur, Mr Hill, impose, permet ou organise.","documents":[{"id":"regles","type":"fiche","modele":"affiche","entete":"Summer camp rules","sousTitre":"Camp Willow — week 1","emoji":"⛺","lignes":[{"texte":"Mr Hill makes us clean the kitchen.","id":"z1"},{"texte":"Mr Hill lets us choose the evening game.","id":"z2"},{"texte":"Mr Hill gets the cook to prepare our snacks.","id":"z3"}],"pied":"Have fun!","source":"Affiche écrite pour l’exercice"}],"questions":[{"enonce":"Touche la ligne où les enfants sont obligés : ils n’ont pas le choix.","aide":"Quel verbe exprime la contrainte ?","type":"zone","document":"regles","multiple":false},{"enonce":"Touche la ligne où les enfants ont la permission de décider.","aide":"Quel verbe exprime la permission ?","type":"zone","document":"regles","multiple":false},{"enonce":"Complète avec le petit mot qui manque.","aide":"Un seul des quatre verbes (*make, have, get, let*) prend un petit mot devant la base verbale.","type":"trous","segments":["Lena got her brother ",0," help her with the tent."],"banque":["for","at","to","with"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"**Mr Hill makes us clean the kitchen** : *make* exprime la contrainte, suivi du complément et de la base verbale."},{"cle":{"type":"zone","ids":["z2"]},"explication":"**Mr Hill lets us choose the evening game** : *let* exprime la permission, suivi de la base verbale."},{"cle":{"type":"trous","trous":[["to"]]},"affichage":"to","explication":"**to** : *get* est le seul des quatre verbes à se construire avec *to* (*I got him to help me*)."}]$ex$::jsonb),
  ('bd47bfd3-6bc0-5c8d-b855-b6963b1ec465'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La facture du garage Riverside","competence":"manier-langue","situation":"Carla n’a rien réparé elle-même : elle a confié sa voiture au garage Riverside. Sa facture le montre ligne par ligne.","documents":[{"id":"facture","type":"fiche","modele":"ticket","entete":"Riverside Garage","sousTitre":"Invoice — Carla Dunn","emoji":"🔧","lignes":[{"texte":"Brakes checked","valeur":"£40","id":"z1"},{"texte":"Oil changed","valeur":"£35","id":"z2"},{"texte":"Windscreen repaired","valeur":"£90","id":"z3"},{"separateur":true},{"texte":"TOTAL","valeur":"£165","gras":true,"id":"z4"}],"pied":"Thank you!","source":"Facture écrite pour l’exercice"}],"questions":[{"enonce":"Touche la ligne qui correspond à la phrase « Carla had her oil changed ».","aide":"Cherche le service qui parle de l’huile (*oil*).","type":"zone","document":"facture","multiple":false},{"enonce":"Écris la phrase : « Carla a fait vérifier ses freins. » Le premier mot est « Carla ».","aide":"Structure : *have* + objet + participe passé.","type":"ordre","items":[{"id":"a","texte":"brakes"},{"id":"b","texte":"had"},{"id":"c","texte":"her"},{"id":"d","texte":"checked"},{"id":"e","texte":"Carla"}]},{"enonce":"Que signifie « Carla had her windscreen repaired » ?","aide":"Qui a fait le travail, d’après la facture ?","type":"choix","options":[{"id":"a","texte":"Carla a fait réparer son pare-brise par le garage"},{"id":"b","texte":"Carla ne répare jamais son pare-brise"},{"id":"c","texte":"Carla a promis de réparer son pare-brise bientôt"},{"id":"d","texte":"Carla a réparé son pare-brise elle-même, au garage"}],"multiple":false},{"enonce":"Qui fait l’action ? Range chaque phrase.","aide":"Cherche la structure *have / get* + objet + participe passé : l’action est confiée à un tiers.","type":"categories","categories":[{"id":"c0","texte":"Je le fais moi-même"},{"id":"c1","texte":"Quelqu’un le fait pour moi"}],"items":[{"id":"i0","texte":"He repaired his bike."},{"id":"i1","texte":"I cut my hair."},{"id":"i2","texte":"I had my hair cut."},{"id":"i3","texte":"She got her car repaired."}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"**Oil changed** : *Carla had her oil changed* veut dire qu’elle a fait changer son huile par le garage."},{"cle":{"type":"ordre","ids":["e","b","c","a","d"]},"explication":"**Carla had her brakes checked** : *have* + objet + participe passé, pour faire faire une chose par un tiers."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Carla a fait réparer son pare-brise par le garage** : *have* + objet + participe passé, l’exécutant n’est pas Carla."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1"}},"explication":"*I cut my hair* : moi ; *I had my hair cut* et *She got her car repaired* : un professionnel ; *He repaired his bike* : lui."}]$ex$::jsonb),
  ('bd47bfd3-6bc0-5c8d-b855-b6963b1ec465'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le voyage scolaire de Zoe au pays de Galles","competence":"manier-langue","situation":"Zoe revient d’un voyage scolaire au pays de Galles. Elle raconte à son ami Jack ce que leur professeur, Mr Fox, leur a imposé, permis ou fait organiser.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"Zoe’s email","blocs":["Hi Jack,","The school trip to Wales was great but tough! Mr Fox made us walk ten kilometres on the first day, and he let us rest only at lunch. I got my sister to lend me her camera, so I have loads of photos. When I get home, I’ll have them printed at the shop.","See you on Monday! Zoe"],"source":"Courriel écrit pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Jack","emoji":"👦","cote":"gauche"},{"nom":"Zoe","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Jack","texte":"Did Mr Fox let you use your phone?"},{"qui":"Zoe","texte":"No! They were all kept in a box."},{"qui":"Jack","texte":"Poor you! Who took the group photo?"},{"qui":"Zoe","texte":"Mr Fox had the hostel manager take it."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le verbe qui montre que Mr Fox a imposé la longue marche : les élèves n’avaient pas le choix.","aide":"Quel verbe exprime la contrainte ?","type":"zone","document":"mail","multiple":false},{"enonce":"Au passif, « Mr Fox let us rest » devient…","aide":"Au passif, *let* est remplacé par un autre verbe de permission, suivi de *to*.","type":"choix","options":[{"id":"a","texte":"We were let rest."},{"id":"b","texte":"We were allowed to rest."},{"id":"c","texte":"We were made to rest."},{"id":"d","texte":"We were let to rest."}],"multiple":false},{"enonce":"Touche le verbe qui suit « had the hostel manager » : sans *to*, avec la base verbale.","aide":"Avec *have*, on ne met pas *to* devant le verbe.","type":"zone","document":"sms","multiple":false},{"enonce":"Complète d’après le courriel de Zoe.","aide":"*Have* + objet + participe passé : l’action est faite par quelqu’un d’autre.","type":"trous","segments":["Zoe will have her photos ",0," at the shop."],"banque":["prints","printing","print","printed"]},{"enonce":"Relie chaque verbe à son sens.","aide":"Pense à la contrainte, à la permission, à la persuasion et au service rendu par un métier.","type":"association","gauche":[{"id":"g0","texte":"make"},{"id":"g1","texte":"let"},{"id":"g2","texte":"get"},{"id":"g3","texte":"have"}],"droite":[{"id":"d0","texte":"obliger"},{"id":"d1","texte":"faire faire par un professionnel"},{"id":"d2","texte":"persuader, obtenir de"},{"id":"d3","texte":"permettre"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m13"]},"explication":"**made** : *make* exprime la contrainte (*Mr Fox made us walk*), suivi du complément et de la base verbale."},{"cle":{"type":"choix","ids":["b"]},"explication":"**We were allowed to rest.** : au passif, on remplace *let* par *allow*."},{"cle":{"type":"zone","ids":["m29"]},"explication":"**take** : *have* + complément + base verbale, sans *to* (*Mr Fox had the manager take the photo*)."},{"cle":{"type":"trous","trous":[["printed"]]},"affichage":"printed","explication":"**printed** : *have* + objet + participe passé, le magasin imprimera les photos."},{"cle":{"type":"association","paires":{"g0":"d0","g3":"d1","g2":"d2","g1":"d3"}},"explication":"*Make* : obliger ; *let* : permettre ; *get* : persuader ; *have* : faire faire par quelqu’un dont c’est le rôle."}]$ex$::jsonb),
  ('365a65f2-f3de-5e28-8847-39105a05c01a'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le vélo de Tom","competence":"comprendre-langue","situation":"Dans le journal d’une petite ville, un article raconte une histoire arrivée à Tom : son vélo a disparu, puis a été retrouvé. Repère les verbes au passif.","documents":[{"id":"article","type":"texte","genre":"article","titre":"Local news","blocs":["Last Friday, Tom’s bike was stolen outside the library. Nobody saw the thief.","Yesterday the bike was found in the river by a fisherman. The police returned it to Tom."],"source":"Article imaginé pour l’exercice"}],"questions":[{"enonce":"Touche tous les mots qui forment les deux verbes au passif.","aide":"Un passif = *be* conjugué + participe passé. Il y en a deux dans l’article.","type":"zone","document":"article","multiple":true},{"enonce":"Pourquoi l’article ne dit-il pas qui a volé le vélo ?","aide":"Relis la phrase qui suit : « Nobody saw the thief. »","type":"choix","options":[{"id":"a","texte":"Le verbe est au présent, pas au passé"},{"id":"b","texte":"Le complément d’agent est toujours interdit"},{"id":"c","texte":"On ne sait pas qui est le voleur"},{"id":"d","texte":"Le voleur est évident pour tout le monde"}],"multiple":false},{"enonce":"Complète le passif.","aide":"Après *was*, on met le participe passé.","type":"trous","segments":["The bike was ",0," in the river."],"banque":["finding","finds","find","found"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4","m5","m16","m17"]},"explication":"**was stolen** et **was found** : *be* (ici au prétérit) + participe passé. *Saw* et *returned* sont des verbes actifs."},{"cle":{"type":"choix","ids":["c"]},"explication":"**On ne sait pas qui est le voleur** : on emploie le passif quand l’agent est inconnu."},{"cle":{"type":"trous","trous":[["found"]]},"affichage":"found","explication":"**found** : le passif se forme avec *be* + participe passé (*was found*)."}]$ex$::jsonb),
  ('365a65f2-f3de-5e28-8847-39105a05c01a'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les nouvelles du musée de Hartley","competence":"manier-langue","situation":"Le musée de Hartley publie un bulletin mensuel. Cette fois, il parle de ses horaires, d’un vol, de travaux et d’une enquête.","documents":[{"id":"bulletin","type":"texte","genre":"article","titre":"Hartley Museum News","blocs":["Hartley Museum is opened every day at nine. Last night, two paintings were stolen.","At the moment, the roof is being repaired, and the new hall will be opened in May. The police say that the case has been solved."],"source":"Bulletin imaginé pour l’exercice"}],"questions":[{"enonce":"Touche les trois mots qui forment le verbe au present perfect passif.","aide":"Le present perfect passif se forme avec *has / have* + *been* + participe passé.","type":"zone","document":"bulletin","multiple":true},{"enonce":"Relie chaque verbe passif au temps qu’il porte.","aide":"C’est *be* qui porte le temps : regarde sa forme (*is*, *were*, *is being*, *will be*, *has been*).","type":"association","gauche":[{"id":"g0","texte":"is opened every day"},{"id":"g1","texte":"were stolen"},{"id":"g2","texte":"is being repaired"},{"id":"g3","texte":"will be opened"},{"id":"g4","texte":"has been solved"}],"droite":[{"id":"d0","texte":"Futur"},{"id":"d1","texte":"Present perfect"},{"id":"d2","texte":"Présent en -ING"},{"id":"d3","texte":"Présent simple"},{"id":"d4","texte":"Prétérit"}]},{"enonce":"Écris la phrase au passif : « Le rapport a été publié. » Le premier mot est « The ».","aide":"Present perfect passif : *has* + *been* + participe passé.","type":"ordre","items":[{"id":"a","texte":"report"},{"id":"b","texte":"has"},{"id":"c","texte":"published"},{"id":"d","texte":"The"},{"id":"e","texte":"been"}]},{"enonce":"Cette nuit, on a volé deux tableaux. Quelle phrase le dit ?","aide":"Le vol est passé et daté (« cette nuit »), et *paintings* est au pluriel.","type":"choix","options":[{"id":"a","texte":"Two paintings were stolen."},{"id":"b","texte":"Two paintings are stolen."},{"id":"c","texte":"Two paintings was stolen."},{"id":"d","texte":"Two paintings have stolen."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m37","m38","m39"]},"explication":"**has been solved** : *has* + *been* + participe passé, le present perfect passif."},{"cle":{"type":"association","paires":{"g3":"d0","g4":"d1","g2":"d2","g0":"d3","g1":"d4"}},"explication":"Le passif garde le même participe ; seul *be* change : *is* (présent), *were* (prétérit), *is being* (-ING), *will be* (futur), *has been* (present perfect)."},{"cle":{"type":"ordre","ids":["d","a","b","e","c"]},"explication":"**The report has been published** : *has been* + participe passé."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Two paintings were stolen.** : *be* au prétérit pluriel (*were*) + participe passé."}]$ex$::jsonb),
  ('365a65f2-f3de-5e28-8847-39105a05c01a'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Les prix de l’école d’Oakfield","competence":"analyser-document","situation":"À l’école d’Oakfield, trois élèves ont reçu un prix lors de la remise des récompenses. Un article parle aussi de l’ancienne bibliothèque de Millbrook, dont on raconte des choses.","documents":[{"id":"prix","type":"tableau","titre":"Prize-giving","colonnes":["Pupil","Prize","Given by"],"lignes":[["Ella","a book","Mr Reed"],["Sam","a medal","the head"],["Nina","a trophy","Ms Grey"]],"source":"Tableau écrit pour l’exercice"},{"id":"biblio","type":"texte","genre":"article","titre":"Millbrook Library","blocs":["The old library of Millbrook is said to have been built in 1850. It is believed that the building will be closed next year, but nobody knows for sure."],"source":"Article imaginé pour l’exercice"}],"questions":[{"enonce":"Touche la case qui dit qui a donné la médaille.","aide":"Cherche la ligne de la médaille, puis la colonne « Given by ».","type":"zone","document":"prix","multiple":false},{"enonce":"Complète d’après le tableau.","aide":"Après *was*, on met le participe passé.","type":"trous","segments":["Sam was ",0," a medal by the head."],"banque":["gave","given","give","giving"]},{"enonce":"Quelle phrase passive correspond à « Mr Reed gave Ella a book » ?","aide":"Le passif de *give* : *be* + participe passé, en commençant par la personne.","type":"choix","options":[{"id":"a","texte":"Ella was given a book by Mr Reed."},{"id":"b","texte":"Ella was gave a book by Mr Reed."},{"id":"c","texte":"Ella given a book was by Mr Reed."},{"id":"d","texte":"Ella gave a book by Mr Reed."}],"multiple":false},{"enonce":"Touche les deux participes passés des tournures impersonnelles (« on dit que », « on croit que »).","aide":"Ils suivent *is* et expriment ce que l’on raconte ou pense.","type":"zone","document":"biblio","multiple":true},{"enonce":"Relie chaque tournure à sa traduction.","aide":"*To have* + participe passé après *is said* renvoie au passé ; *to be* au présent.","type":"association","gauche":[{"id":"g0","texte":"It is said that…"},{"id":"g1","texte":"He is said to have left"},{"id":"g2","texte":"It is believed that…"},{"id":"g3","texte":"He is said to be…"}],"droite":[{"id":"d0","texte":"On croit que…"},{"id":"d1","texte":"Il serait…"},{"id":"d2","texte":"On dit que…"},{"id":"d3","texte":"Il aurait quitté…"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c2"]},"explication":"La médaille a été donnée par **the head** (colonne « Given by »)."},{"cle":{"type":"trous","trous":[["given"]]},"affichage":"given","explication":"**given** : *Sam was given a medal* — on commence par la personne."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Ella was given a book by Mr Reed.** : le participe passé de *give* est *given*, et l’anglais commence volontiers par la personne."},{"cle":{"type":"zone","ids":["m6","m15"]},"explication":"**said** et **believed** : *is said to…* et *is believed that…* sont des tournures impersonnelles."},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g0":"d2","g1":"d3"}},"explication":"*It is said that…* : on dit que ; *is said to have left* : aurait quitté ; *is believed that…* : on croit que ; *is said to be…* : serait."}]$ex$::jsonb),
  ('92c7f3de-f6a1-502a-aa3e-188bd7873580'::uuid, 1, 1, 5, 20, 3,
