  ('92c7f3de-f6a1-502a-aa3e-188bd7873580'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les consignes de Mr Ellis","competence":"manier-langue","situation":"Lundi, Mr Ellis a donné des consignes à la classe 2B, puis il a posé deux questions. Elena les rapporte à une camarade absente.","documents":[{"id":"consignes","type":"fiche","modele":"affiche","entete":"Mr Ellis, class 2B","sousTitre":"What he said on Monday","emoji":"📚","lignes":[{"texte":"“Open your books.”","id":"z1"},{"texte":"“Don’t talk during the test.”","id":"z2"},{"texte":"“Where is your homework?”","id":"z3"},{"texte":"“Do you understand?”","id":"z4"}],"source":"Affiche écrite pour l’exercice"}],"questions":[{"enonce":"Touche la phrase qui, rapportée, s’introduit par « if » (il n’y a pas de mot interrogatif).","aide":"Une question sans mot interrogatif (*where, what…*) s’introduit par *if* ou *whether*.","type":"zone","document":"consignes","multiple":false},{"enonce":"Rapporte la question « Where is your homework? » Le premier mot est « He ».","aide":"Plus d’inversion ni de *do*, le verbe recule d’un cran et le pronom s’adapte.","type":"ordre","items":[{"id":"a","texte":"asked"},{"id":"b","texte":"homework"},{"id":"c","texte":"was"},{"id":"d","texte":"our"},{"id":"e","texte":"where"},{"id":"f","texte":"He"}]},{"enonce":"Rapporte l’ordre négatif « Don’t talk. »","aide":"Un ordre négatif se rapporte avec un infinitif négatif.","type":"trous","segments":["He told us ",0," to talk during the test."],"banque":["not","doesn’t","no","don’t"]},{"enonce":"Relie chaque phrase de Mr Ellis à sa version rapportée.","aide":"Ordre : *told us (not) to* ; question avec mot interrogatif : *asked where* ; question fermée : *asked if*.","type":"association","gauche":[{"id":"g0","texte":"“Open your books.”"},{"id":"g1","texte":"“Don’t talk during the test.”"},{"id":"g2","texte":"“Where is your homework?”"},{"id":"g3","texte":"“Do you understand?”"}],"droite":[{"id":"d0","texte":"He told us to open our books."},{"id":"d1","texte":"He asked if we understood."},{"id":"d2","texte":"He asked where our homework was."},{"id":"d3","texte":"He told us not to talk during the test."}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z4"]},"explication":"**“Do you understand?”** : question fermée, donc *He asked if we understood*."},{"cle":{"type":"ordre","ids":["f","a","e","d","b","c"]},"explication":"**He asked where our homework was** : pas d’inversion, *is* devient *was*, *your* devient *our*."},{"cle":{"type":"trous","trous":[["not"]]},"affichage":"not","explication":"**not** : un ordre négatif devient *not to* + base verbale (*He told us not to talk*)."},{"cle":{"type":"association","paires":{"g0":"d0","g3":"d1","g2":"d2","g1":"d3"}},"explication":"Ordre : infinitif (*told us to / not to*) ; question : *asked where…* sans inversion, ou *asked if…* quand il n’y a pas de mot interrogatif."}]$ex$::jsonb),
  ('92c7f3de-f6a1-502a-aa3e-188bd7873580'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"L’interview avant le festival","competence":"analyser-document","situation":"Une journaliste du lycée a interviewé le directeur du festival de musique. Elle a rédigé un brouillon rapportant l’interview, mais il contient deux fautes de discours indirect. À toi de les trouver.","documents":[{"id":"interview","type":"dialogue","modele":"sms","titre":"The interview","participants":[{"nom":"Reporter","emoji":"🎤","cote":"gauche"},{"nom":"Director","emoji":"🎪","cote":"droite"}],"repliques":[{"qui":"Reporter","texte":"How do you feel today?"},{"qui":"Director","texte":"We are very excited today. We have sold 5,000 tickets, and we will open the gates tomorrow."},{"qui":"Reporter","texte":"Do you expect rain?"},{"qui":"Director","texte":"Not at all!"}],"source":"Interview écrite pour l’exercice"},{"id":"brouillon","type":"texte","genre":"article","titre":"The journalist’s draft","blocs":["The director said me that they were very excited. He said they had sold 5,000 tickets and that they would open the gates.","I asked him did he expect rain. He answered that he was sure the weather would be fine."],"source":"Brouillon écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot en trop dans la première phrase : *say* n’a pas de complément de personne.","aide":"Cherche un pronom qui suit directement *said*.","type":"zone","document":"brouillon","multiple":false},{"enonce":"Touche l’auxiliaire qui n’a rien à faire dans une question indirecte.","aide":"Dans une question indirecte, il n’y a ni inversion ni *do*.","type":"zone","document":"brouillon","multiple":false},{"enonce":"Rapporte « we will open the gates tomorrow ».","aide":"Au discours indirect passé, *tomorrow* change de forme.","type":"trous","segments":["He said they would open the gates ",0,"."],"banque":["then","the next day","tomorrow","the day before"]},{"enonce":"Écris la bonne version de la question de la journaliste. Le premier mot est « I ».","aide":"Question fermée : *if* ; le verbe recule d’un cran, sans *do*.","type":"ordre","items":[{"id":"a","texte":"he"},{"id":"b","texte":"rain"},{"id":"c","texte":"him"},{"id":"d","texte":"if"},{"id":"e","texte":"asked"},{"id":"f","texte":"I"},{"id":"g","texte":"expected"}]},{"enonce":"Relie chaque mot du discours direct à sa forme au discours indirect.","aide":"Tout se déplace d’un cran vers le passé et vers l’éloignement.","type":"association","gauche":[{"id":"g0","texte":"will"},{"id":"g1","texte":"must"},{"id":"g2","texte":"tomorrow"},{"id":"g3","texte":"yesterday"},{"id":"g4","texte":"here"}],"droite":[{"id":"d0","texte":"there"},{"id":"d1","texte":"the next day"},{"id":"d2","texte":"had to"},{"id":"d3","texte":"would"},{"id":"d4","texte":"the day before"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3"]},"explication":"**said me** est une faute : *say* ne prend pas de complément de personne (*He said that…* ou *He told me that…*)."},{"cle":{"type":"zone","ids":["m27"]},"explication":"**did** est en trop : la question indirecte s’écrit *I asked him if he expected rain*, sans *do*."},{"cle":{"type":"trous","trous":[["the next day"]]},"affichage":"the next day","explication":"**the next day** : *tomorrow* devient *the next day* au discours indirect passé."},{"cle":{"type":"ordre","ids":["f","e","c","d","a","g","b"]},"explication":"**I asked him if he expected rain** : *if*, pas d’inversion et *expect* devient *expected*."},{"cle":{"type":"association","paires":{"g4":"d0","g2":"d1","g1":"d2","g0":"d3","g3":"d4"}},"explication":"*Will* devient *would*, *must* devient *had to*, *tomorrow* devient *the next day*, *yesterday* devient *the day before*, *here* devient *there*."}]$ex$::jsonb),
