  ('8276dae0-32df-5f05-b2bc-df822d05522f'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le blog de Maya sur la mode","competence":"comprendre-langue","situation":"Maya tient un blog sur la mode et l’apparence. Elle y parle de normes de beauté, d’estime de soi et de l’histoire des modes qui ont dit « non » à la norme.","documents":[{"id":"blog","type":"texte","genre":"article","titre":"Maya’s blog","blocs":["Last week, a teacher showed us old photos of beauty pageants. Everybody had to fit the same stereotype of the “perfect” look. It made me think about my own outfit and my own looks.","Body shaming is hurtful: I know girls who were mocked at school. But the body positivity movement shows all kinds of bodies on social media, and it has helped my self-esteem. I try to stand out, not to conform."],"source":"Blog écrit pour l’exercice"},{"id":"modes","type":"tableau","titre":"Fashion as a message","colonnes":["Who","When","What"],"lignes":[["Mary Quant","1960s","the miniskirt"],["Vivienne Westwood","1970s","punk fashion"],["David Bowie","1972","Ziggy Stardust"]],"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux mots qui veulent dire « se démarquer ».","aide":"C’est le contraire de se conformer.","type":"zone","document":"blog","multiple":true},{"enonce":"Relie chaque mot du blog à sa traduction.","aide":"Repère le mot qui parle de moquerie, celui qui parle de vêtements et celui qui parle de confiance en soi.","type":"association","gauche":[{"id":"g0","texte":"self-esteem"},{"id":"g1","texte":"body shaming"},{"id":"g2","texte":"outfit"},{"id":"g3","texte":"to conform"}],"droite":[{"id":"d0","texte":"la tenue"},{"id":"d1","texte":"le fait de moquer le physique de quelqu’un"},{"id":"d2","texte":"l’estime de soi"},{"id":"d3","texte":"se conformer"}]},{"enonce":"Complète la définition.","aide":"Maya écrit que cette pratique est blessante (*hurtful*).","type":"trous","segments":["Mocking someone’s body is called body ",0,"."],"banque":["language","shaming","building","lifting"]},{"enonce":"Touche la case qui nom