   $ex${"titre":"La montre du grand-père","competence":"comprendre-langue","situation":"Leo discute avec son grand-père des différences entre leurs deux époques, en particulier du logement. Une étude invente quelques chiffres sur l’accès à la propriété.","documents":[{"id":"dialogue","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Grandpa","emoji":"👴","cote":"gauche"},{"nom":"Leo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Grandpa","texte":"When I was twenty-five, I owned my own flat. Now my grandson still lives with his parents!"},{"qui":"Leo","texte":"Grandpa, flats are very expensive today. And you inherited some money from your father."},{"qui":"Grandpa","texte":"True. Your great-grandfather handed down this old watch to me, and one day I will give it to you."}],"source":"Messages écrits pour l’exercice"},{"id":"proprio","type":"graphique","forme":"barres","titre":"Home ownership by age group","categories":["25–34","35–44","45–54","65 and over"],"series":[{"nom":"Homeowners","valeurs":[30,55,70,80],"teinte":"turquoise"}],"axeY":{"titre":"Homeowners","unite":"%","min":0,"max":100,"pas":20},"axeX":{"titre":"Age group"},"valeurs":false,"source":"Chiffres inventés pour l’exercice"}],"questions":[{"enonce":"Touche les deux mots du message de Grandpa qui signifient « transmettre ».","aide":"C’est un verbe à particule qui parle de la montre transmise de père en fils.","type":"zone","document":"dialogue","multiple":true},{"enonce":"Exprime l’opposition entre deux générations.","aide":"Le mot doit opposer deux situations.","type":"trous","segments":["My grandfather bought a flat at twenty-five, ",0," I will rent for years."],"banque":["whereas","because","unless","so"]},{"enonce":"Touche la barre du groupe d’âge qui compte le moins de propriétaires.","aide":"Cherche la barre la plus basse.","type":"zone","document":"proprio","multiple":false},{"enonce":"De combien de points la part de propriétaires des 65 ans et plus dépasse-t-elle cel