   $ex${"titre":"Deux Robin des Bois","competence":"analyser-document","situation":"Le cinéclub de ta classe compare deux versions d’une même légende : une version classique et une version moderne imaginée pour l’exercice. Ana et Tom en discutent par messages.","documents":[{"id":"versions","type":"texte","genre":"article","titre":"Two versions of a legend","blocs":["Version A. Robin lives in Sherwood Forest. He steals from the rich to give to the poor, and the Sheriff of Nottingham hunts him.","Version B. Robin is a young hacker in a modern city. He leaks secret bank files and shares the money with poor families, and a security chief hunts him."],"source":"Résumés écrits pour l’exercice"},{"id":"debat","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Ana","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Ana","texte":"Do you prefer version A or version B?"},{"qui":"Tom","texte":"I prefer A. Version B really departs from the legend, but it gives the hero a modern world."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Range chaque élément dans la bonne version.","aide":"Relis les deux paragraphes du texte.","type":"categories","categories":[{"id":"c0","texte":"Version A"},{"id":"c1","texte":"Version B"}],"items":[{"id":"i0","texte":"Robin leaks secret bank files."},{"id":"i1","texte":"Robin lives in Sherwood Forest."},{"id":"i2","texte":"The Sheriff of Nottingham hunts Robin."},{"id":"i3","texte":"Robin is a young hacker."}]},{"enonce":"Touche le verbe qui dit que la version B s’éloigne de l’original.","aide":"C’est un verbe au présent, avec -s.","type":"zone","document":"debat","multiple":false},{"enonce":"Complète la phrase du critique.","aide":"Le sujet est *the director* : 3e personne du singulier.","type":"trous","segments":["The director ",0," the story by setting it in modern London."],"banque":["updating","to update","updates","update"]},{"enonce":"Quel élément de la légende la version B conserve-t-elle ?","aide":"Compare ce que fait Robin dans les deux versions.","type":"choix","options":[{"id":"a","texte":"Robin vit dans la forêt de Sherwood"},{"id":"b","texte":"Robin aide des familles pauvres"},{"id":"c","texte":"Robin tire à l’arc"},{"id":"d","texte":"Robin est chassé par le shérif de Nottingham"}],"multiple":false},{"enonce":"Relie chaque expression à sa traduction.","aide":"Repère *faithful* (fidèle) et *strikes* (frappe).","type":"association","gauche":[{"id":"g0","texte":"This version is more faithful to…"},{"id":"g1","texte":"It departs from the original."},{"id":"g2","texte":"What strikes me is that…"},{"id":"g3","texte":"The director updates the story by…"}],"droite":[{"id":"d0","texte":"Elle s’éloigne de l’original."},{"id":"d1","texte":"Le réalisateur actualise l’histoire en…"},{"id":"d2","texte":"Cette version est plus fidèle à…"},{"id":"d3","texte":"Ce qui me frappe, c’est que…"}]}]}$ex$::jsonb,
