   $ex${"titre":"Cinq livres, cinq pays","competence":"lire-tableau","situation":"Pour son exposé, Naomi a dressé la liste de cinq livres du Commonwealth dans un tableau en anglais. Lis-le avec elle.","documents":[{"id":"books","type":"tableau","titre":"Naomi’s reading list","colonnes":["Title","Author","Country","Year"],"lignes":[["Things Fall Apart","Chinua Achebe","Nigeria",1958],["Midnight’s Children","Salman Rushdie","India",1981],["Long Walk to Freedom","Nelson Mandela","South Africa",1994],["The God of Small Things","Arundhati Roy","India",1997],["Half of a Yellow Sun","Chimamanda Ngozi Adichie","Nigeria",2006]],"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche la case qui donne l’auteur du livre publié en 1994.","aide":"Repère la ligne de 1994, puis la colonne « Author ».","type":"zone","document":"books","multiple":false},{"enonce":"Combien de livres du tableau viennent d’Inde (*India*) ?","aide":"Compte les lignes où la colonne « Country » dit India.","type":"nombre"},{"enonce":"Relie chaque livre à ce qu’il raconte.","aide":"Pense au pays de chaque auteur et à l’événement historique qui l’a marqué.","type":"association","gauche":[{"id":"g0","texte":"Things Fall Apart"},{"id":"g1","texte":"Midnight’s Children"},{"id":"g2","texte":"Long Walk to Freedom"},{"id":"g3","texte":"Half of a Yellow Sun"}],"droite":[{"id":"d0","texte":"Une société igbo bouleversée par l’arrivée des colons"},{"id":"d1","texte":"Les enfants nés à minuit le jour de l’indépendance"},{"id":"d2","texte":"La guerre du Biafra"},{"id":"d3","texte":"L’autobiographie d’un prisonnier devenu président"}]}]}$ex$::jsonb,
