   $ex${"titre":"Ce que l’Empire a laissé derrière lui","competence":"analyser-document","situation":"Ravi, élève de 2de à Leeds, a écrit un court article pour le Commonwealth Day. Lis-le, puis repère les héritages dans le texte et sur la carte.","documents":[{"id":"art","type":"texte","genre":"article","titre":"Commonwealth Day","blocs":["Every year, on the second Monday in March, we celebrate Commonwealth Day at school. Today 56 countries belong to the Commonwealth, from huge India to tiny Nauru.","Many of them share a British heritage: English is a common language, their Parliament works like Westminster, their judges follow common law, and their teams play cricket.","Last year our class read Half of a Yellow Sun, a novel about the Biafran war. The members have no common religion, regime or continent, but the Commonwealth Charter says they share the same values."],"source":"Article écrit pour l’exercice"},{"id":"carte","type":"carte","titre":"Some Commonwealth countries","fond":"monde","cadrage":[-20,-38,100,40],"regions":[{"code":"NGA","teinte":"vert","motif":"clair"},{"code":"IND","teinte":"vert","motif":"clair"},{"code":"ZAF","teinte":"vert","motif":"clair"},{"code":"KEN","teinte":"vert","motif":"clair"},{"code":"GHA","teinte":"vert","motif":"clair"}],"regionsCliquables":true,"legende":[{"teinte":"vert","motif":"clair","texte":"Member of the Commonwealth"}],"source":"Carte simplifiée pour l’exercice"}],"questions":[{"enonce":"Touche les quatre mots de l’article qui désignent un héritage britannique : la langue, le Parlement, le droit et le sport.","aide":"Relis le deuxième paragraphe, après « British heritage ».","type":"zone","document":"art","multiple":true},{"enonce":"L’article cite un roman sur la guerre du Biafra. Touche, sur la carte, le pays de son auteure, Chimamanda Ngozi Adichie.","aide":"Le Biafra était une région de l’Afrique de l’Ouest, sur le golfe de Guinée.","type":"zone","document":"carte","multiple":false},{"enonce":"L’article cite deux membres extrêmes : l’Inde et Nauru. Combien le Commonwealth compte-t-il d’autres pays membres ?","aide":"Cherche le nombre total de membres dans le premier paragraphe, puis retire les deux pays cités.","type":"nombre"},{"enonce":"Selon l’article, qu’est-ce qui rassemble ces pays malgré leurs différences ?","aide":"Relis la dernière phrase : l’article dit ce que ces pays n’ont PAS en commun.","type":"choix","options":[{"id":"a","texte":"Un continent qu’ils partagent tous"},{"id":"b","texte":"Une religion partagée par tous"},{"id":"c","texte":"Les valeurs de leur Charte commune"},{"id":"d","texte":"Un régime politique unique"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m34","m40","m48","m53"]},"explication":"Les héritages sont **English** (la langue), **Parliament** (le système de Westminster), **law** (la common law) et **cricket** (le sport)."},{"cle":{"type":"zone","ids":["NGA"]},"explication":"La guerre du Biafra a eu lieu au **Nigeria**, pays d’Adichie, comme celui d’Achebe."},{"cle":{"type":"nombre","valeur":54,"tolerance":0},"affichage":"54","explication":"56 membres − 2 pays cités = **54** autres pays."},{"cle":{"type":"choix","ids":["c"]},"explication":"Ni religion, ni régime, ni continent : ce sont les **valeurs de la Commonwealth Charter** (2013) qui les rassemblent."}]$ex$::jsonb),
