   $ex${"titre":"Du roman d’Achebe à la Charte de 2013","competence":"se-reperer-temps","situation":"Pour son exposé, Léa a placé sur une frise cinq livres du Commonwealth et la Commonwealth Charter. Elle a aussi écrit en anglais le début de sa conclusion.","documents":[{"id":"frise","type":"frise","titre":"Books and a charter","debut":1950,"fin":2020,"pas":10,"evenements":[{"id":"z1","date":1958,"nom":"Things Fall Apart"},{"id":"z2","date":1981,"nom":"Midnight’s Children"},{"id":"z3","date":1994,"nom":"Long Walk to Freedom"},{"id":"z4","date":1997,"nom":"God of Small Things"},{"id":"z5","date":2006,"nom":"Yellow Sun"},{"id":"z6","date":2013,"nom":"Commonwealth Charter"}],"source":"Frise écrite pour l’exercice"},{"id":"concl","type":"texte","genre":"article","titre":"Léa’s conclusion","blocs":["Through this novel, Achebe gives a voice to the colonised. He writes in English, the language of the Empire, but he tells the story of an Igbo society. In this way, the Empire writes back."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche sur la frise le roman qui raconte les castes et une famille du Kerala, en Inde.","aide":"Deux livres de la frise viennent d’Inde : l’un parle des enfants de l’indépendance, l’autre des castes.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent la parution de *Things Fall Apart* de celle de *Half of a Yellow Sun* ?","aide":"Relève les deux dates sur la frise, puis soustrais.","type":"nombre"},{"enonce":"D’après la conclusion de Léa, pourquoi le choix de l’anglais est-il un geste fort pour Achebe ?","aide":"Relis la dernière phrase : « the Empire writes back ».","type":"choix","options":[{"id":"a","texte":"Il veut que son roman soit lu surtout par les habitants du Royaume-Uni"},{"id":"b","texte":"Il refuse de montrer la société igbo pour ne pas choquer ses lecteurs"},{"id":"c","texte":"Il imite le style des écrivains britanniques de son époque pour leur plaire"},{"id":"d","texte":"Il retourne la langue de l’Empire pour raconter l’histoire des colonisés"}],"multiple":false},{"enonce":"Remets les mots dans l’ordre pour écrire une phrase de la conclusion. Le premier mot est « These ».","aide":"Sujet, verbe, puis complément : *these countries* … *share* … *a common heritage*.","type":"ordre","items":[{"id":"a","texte":"common"},{"id":"b","texte":"countries"},{"id":"c","texte":"share"},{"id":"d","texte":"a"},{"id":"e","texte":"These"},{"id":"f","texte":"heritage"}]},{"enonce":"Touche l’événement de la frise qui énonce les valeurs communes des membres : démocratie, droits humains, État de droit.","aide":"Ce n’est pas un roman : c’est un texte officiel.","type":"zone","document":"frise","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z4"]},"explication":"**The God of Small Things** (Arundhati Roy, 1997) parle des castes et de la famille ; *Midnight’s Children* raconte l’indépendance."},{"cle":{"type":"nombre","valeur":48,"tolerance":0},"affichage":"48","explication":"2006 − 1958 = **48 ans**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Achebe utilise **la langue de l’Empire** pour raconter l’histoire des colonisés : c’est le sens de *the Empire writes back*."},{"cle":{"type":"ordre","ids":["e","b","c","d","a","f"]},"explication":"**These countries share a common heritage** : sujet, verbe, complément."},{"cle":{"type":"zone","ids":["z6"]},"explication":"La **Commonwealth Charter** (2013) énonce ces valeurs communes."}]$ex$::jsonb),
  ('90a049c5-9e96-5aec-9d98-dc55c26b72fb'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les SMS de Zoe et Ben","competence":"comprendre-langue","situation":"Zoe et Ben échangent des messages après les vacances. Repère les pronoms réfléchis.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Zoe","emoji":"👧","cote":"gauche"},{"nom":"Ben","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Zoe","texte":"I taught myself to play the guitar this summer!"},{"qui":"Ben","texte":"Great! Did you hurt yourself at first?"},{"qui":"Zoe","texte":"A little. My cat scared itself with the noise and hid under the bed."},{"qui":"Ben","texte":"Poor cat! Let’s enjoy ourselves on Saturday."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les quatre pronoms réfléchis des messages.","aide":"Un pronom réfléchi se termine par -self ou -selves.","type":"zone","document":"sms","multiple":true},{"enonce":"Relie chaque sujet à son pronom réfléchi.","aide":"Au singulier on termine par -self, au pluriel par -selves.","type":"association","gauche":[{"id":"g0","texte":"I"},{"id":"g1","texte":"you (une personne)"},{"id":"g2","texte":"it"},{"id":"g3","texte":"we"}],"droite":[{"id":"d0","texte":"yourself"},{"id":"d1","texte":"itself"},{"id":"d2","texte":"ourselves"},{"id":"d3","texte":"myself"}]},{"enonce":"Dans « Let’s enjoy ourselves on Saturday », qui va s’amuser ?","aide":"« Let’s » veut dire « let us » : qui est inclus dans « us » ?","type":"choix","options":[{"id":"a","texte":"Zoe toute seule, sans Ben"},{"id":"b","texte":"Le chat de Zoe uniquement"},{"id":"c","texte":"Zoe et Ben, tous les deux"},{"id":"d","texte":"Seulement Ben, pas Zoe"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2","m13","m21","m34"]},"explication":"Les quatre pronoms sont **myself, yourself, itself, ourselves**."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"**I → myself, you → yourself, it → itself, we → ourselves**."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Ourselves** reprend « us » : Ben et Zoe, ensemble."}]$ex$::jsonb),
  ('90a049c5-9e96-5aec-9d98-dc55c26b72fb'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les jumeaux se regardent","competence":"manier-langue","situation":"Anna et Leo sont jumeaux. Dans leur histoire, certains « se » sont des réfléchis et d’autres des réciproques : l’anglais ne les confond pas.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"The twins’ day","blocs":["Anna and Leo are twins. They woke up at seven and got dressed quickly. Then they looked at each other and laughed, because they were wearing the same T-shirt.","Anna looked at herself in the mirror and said, “I will change!” Leo made himself a sandwich. In the evening, they helped each other with their homework."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les pronoms réciproques : ceux où l’action va de l’un à l’autre.","aide":"Cherche l’expression en deux mots qui veut dire « l’un l’autre ».","type":"zone","document":"recit","multiple":true},{"enonce":"Touche les pronoms réfléchis : ceux où l’action revient sur le sujet.","aide":"Anna se regarde elle-même ; Leo se prépare quelque chose à lui-même.","type":"zone","document":"recit","multiple":true},{"enonce":"Range chaque phrase : réfléchi (sur soi-même) ou réciproque (l’un l’autre).","aide":"Un seul sujet qui agit sur lui-même : réfléchi. Deux personnes ou plus qui agissent l’une sur l’autre : réciproque.","type":"categories","categories":[{"id":"c0","texte":"Réfléchi"},{"id":"c1","texte":"Réciproque"}],"items":[{"id":"i0","texte":"He cut himself."},{"id":"i1","texte":"They looked at each other."},{"id":"i2","texte":"We helped each other."},{"id":"i3","texte":"She looked at herself in the mirror."},{"id":"i4","texte":"I taught myself to swim."},{"id":"i5","texte":"They wrote to each other every week."}]},{"enonce":"Complète la phrase.","aide":"Anna appelle Leo et Leo appelle Anna : l’action va de l’un à l’autre.","type":"trous","segments":["At night, Anna and Leo phone ",0," to say goodnight."],"banque":["herself","ourselves","themselves","each other"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m18","m19","m51","m52"]},"explication":"**each other** (deux fois) : les jumeaux se regardent et s’aident l’un l’autre."},{"cle":{"type":"zone","ids":["m32","m43"]},"explication":"**herself** et **himself** : l’action revient sur Anna et sur Leo."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0","i4":"c0","i5":"c1"}},"explication":"**-self / -selves** : l’action revient sur le sujet. **each other** : elle va de l’un à l’autre."},{"cle":{"type":"trous","trous":[["each other"]]},"affichage":"each other","explication":"**each other** : chacun appelle l’autre ; *themselves* voudrait dire que chacun s’appelle lui-même."}]$ex$::jsonb),
  ('90a049c5-9e96-5aec-9d98-dc55c26b72fb'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le courrier de Jack à sa famille d’accueil","competence":"analyser-document","situation":"Jack, un élève français, écrit à son correspondant anglais. Son brouillon contient des « self » en trop : il traduit mot à mot des verbes pronominaux français.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"Jack’s draft","blocs":["Hi Max, thanks for your message! I arrived in Leeds on Monday and I introduced myself to your parents.","On Tuesday I was late, so I hurried myself to the bus stop. At school I enjoyed myself a lot, and I felt myself very welcome. I remembered myself your sister’s name only on Wednesday!","Your mum made the cake herself, and I made myself a cup of tea to say thank you. See you soon! Jack"],"source":"Brouillon écrit pour l’exercice, avec des erreurs"},{"id":"memo","type":"tableau","titre":"Aide-mémoire","colonnes":["Français","Anglais"],"lignes":[["se lever","to get up"],["se réveiller","to wake up"],["se souvenir","to remember"],["se dépêcher","to hurry"],["se sentir bien","to feel good"],["s’habiller","to get dressed"]],"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche les trois « myself » de trop : ceux où l’anglais n’a pas de pronom réfléchi.","aide":"Pour chaque verbe (*hurry*, *feel*, *remember*), demande-toi si l’anglais en veut un. *Introduce* et *enjoy*, eux, en veulent un.","type":"zone","document":"mail","multiple":true},{"enonce":"Dans l’aide-mémoire, quel verbe anglais correspond à « se dépêcher » ?","aide":"Cherche « se dépêcher » dans la colonne de gauche.","type":"texte","placeholder":"Un mot"},{"enonce":"Complète la phrase.","aide":"Les cousins se serrent l’un l’autre ; chaque invité s’amuse lui-même.","type":"trous","segments":["The two cousins hugged ",0," and then all the guests enjoyed ",1,"."],"banque":["themselves","myself","ourselves","each other"]},{"enonce":"Dans « Your mum made the cake herself », que ajoute « herself » ?","aide":"Ici le pronom ne remplace pas un complément : il insiste.","type":"choix","options":[{"id":"a","texte":"Elle l’a fait elle-même, sans aide"},{"id":"b","texte":"Elle l’a fait pour se faire plaisir"},{"id":"c","texte":"Elle l’a fait pour elle seule"},{"id":"d","texte":"Elle s’est fait mal en le préparant"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m27","m42","m47"]},"explication":"On dit **I hurried**, **I felt very welcome**, **I remembered** : pas de pronom. *Introduced myself*, *enjoyed myself* et *made myself a cup of tea* sont corrects."},{"cle":{"type":"texte","acceptes":["hurry","to hurry"]},"affichage":"hurry","explication":"**to hurry** : « se dépêcher » se dit sans pronom en anglais (*I hurried to the bus stop*)."},{"cle":{"type":"trous","trous":[["each other"],["themselves"]]},"affichage":"each other · themselves","explication":"**each other** (l’un l’autre) puis **themselves** (les invités s’amusent : *enjoy yourselves / themselves*)."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le réfléchi peut **insister** : *made it herself* = elle l’a fait elle-même."}]$ex$::jsonb),
