   $ex${"titre":"L’affiche de la kermesse d’Oakfield","competence":"comprendre-langue","situation":"Le lycée d’Oakfield organise une fête d’été. Lis l’affiche et repère comment l’anglais assemble les mots.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","entete":"Oakfield Summer Fair","sousTitre":"Saturday, 10 a.m. to 4 p.m.","emoji":"🎪","lignes":[{"texte":"Cake stall","valeur":"10 a.m.","id":"z1"},{"texte":"Ten-minute magic show","valeur":"11 a.m.","id":"z2"},{"texte":"Book sale","valeur":"1 p.m.","id":"z3"},{"texte":"Tea tent","valeur":"3 p.m.","id":"z4"}],"pied":"Everyone is welcome!","source":"Affiche imaginée pour l’exercice"}],"questions":[{"enonce":"Touche la ligne qui contient un adjectif composé (des mots reliés par des traits d’union).","aide":"Cherche les traits d’union.","type":"zone","document":"affiche","multiple":false},{"enonce":"Dans « Cake stall », quel mot dit de quoi on parle ?","aide":"En anglais, on lit un nom composé de droite à gauche.","type":"choix","options":[{"id":"a","texte":"cake"},{"id":"b","texte":"stall"},{"id":"c","texte":"Saturday"},{"id":"d","texte":"10 a.m."}],"multiple":false},{"enonce":"Relie chaque nom composé à son sens.","aide":"Le nom de droite dit toujours de quoi on parle.","type":"association","gauche":[{"id":"g0","texte":"a teacup"},{"id":"g1","texte":"a cup of tea"},{"id":"g2","texte":"a car park"},{"id":"g3","texte":"a sports car"}],"droite":[{"id":"d0","texte":"une tasse de thé"},{"id":"d1","texte":"une tasse à thé"},{"id":"d2","texte":"un parking"},{"id":"d3","texte":"une voiture de sport"}]}]}$ex$::jsonb,
