  ('3ddb3dce-98f7-588b-9831-f891db437837'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un portefeuille retrouvé à Leeds","competence":"manier-langue","situation":"Un journal local raconte comment un garçon a rendu un portefeuille perdu. L’article est plein de mots composés.","documents":[{"id":"news","type":"texte","genre":"article","titre":"Lost and found","blocs":["A twelve-year-old boy from Leeds has found a lost wallet at a bus stop. The owner is a well-known actor, who called it a heart-warming story. The boy waited ten minutes and gave the wallet to a police officer."],"source":"Article imaginé pour l’exercice"}],"questions":[{"enonce":"Touche les trois adjectifs composés de l’article.","aide":"Ils s’écrivent avec un trait d’union et se placent devant un nom.","type":"zone","document":"news","multiple":true},{"enonce":"Dans « a police officer », quel mot est le nom principal ?","aide":"Le nom principal est le dernier.","type":"choix","options":[{"id":"a","texte":"officer"},{"id":"b","texte":"wallet"},{"id":"c","texte":"police"},{"id":"d","texte":"a"}],"multiple":false},{"enonce":"Comment dire « un voyage de trois heures » avec un adjectif composé ?","aide":"Le premier élément reste au singulier, comme dans *twelve-year-old*.","type":"choix","options":[{"id":"a","texte":"a journey three-hour"},{"id":"b","texte":"a three hour’s journey"},{"id":"c","texte":"a three-hours journey"},{"id":"d","texte":"a three-hour journey"}],"multiple":false},{"enonce":"Relie chaque expression française à son équivalent anglais.","aide":"Une quantité ou un contenu : *of*. Une catégorie de durée : *’s*. Sinon : nom + nom.","type":"association","gauche":[{"id":"g0","texte":"un conducteur de bus"},{"id":"g1","texte":"un chien de garde"},{"id":"g2","texte":"une journée de travail"},{"id":"g3","texte":"une paire de gants"}],"droite":[{"id":"d0","texte":"a bus driver"},{"id":"d1","texte":"a day’s work"},{"id":"d2","texte":"a guard dog"},{"id":"d3","texte":"a pair of gloves"}]}]}$ex$::jsonb,
