  ('3ddb3dce-98f7-588b-9831-f891db437837'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le ticket de caisse et l’avis de Clara","competence":"analyser-document","situation":"Clara a écrit un avis sur sa sortie shopping avec sa nièce et gardé son ticket. Son texte contient des fautes sur les mots composés.","documents":[{"id":"avis","type":"texte","genre":"lettre","titre":"Clara’s review","blocs":["Last Saturday I took my ten-years-old niece to a toys shop. We went on a two-hours trip by bus and bought a pair of gloves, a teacup, a children’s book and a sports bag. I paid with two £20 notes."],"source":"Avis écrit pour l’exercice, avec des erreurs"},{"id":"ticket","type":"fiche","modele":"ticket","entete":"Oakfield Shop","sousTitre":"Receipt","emoji":"🧾","lignes":[{"texte":"a pair of gloves","valeur":"£8","id":"z1"},{"texte":"a teacup","valeur":"£5","id":"z2"},{"texte":"a children’s book","valeur":"£6","id":"z3"},{"texte":"a sports bag","valeur":"£15","id":"z4"}],"pied":"Thank you!","source":"Ticket imaginé pour l’exercice"}],"questions":[{"enonce":"Touche les trois erreurs sur les mots composés dans l’avis de Clara.","aide":"Le premier nom ou l’élément de durée ne prend jamais de -s devant un autre nom.","type":"zone","document":"avis","multiple":true},{"enonce":"Touche sur le ticket l’article destiné aux enfants.","aide":"Cherche le nom composé avec « ’s » qui veut dire « pour… ».","type":"zone","document":"ticket","multiple":false},{"enonce":"Corrige les erreurs de l’avis de Clara.","aide":"Un adjectif composé reste au singulier : pas de -s.","type":"trous","segments":["My niece is a ",0," girl and we took a ",1," trip."],"banque":["two-hour","two-hours","ten-year-old","ten-years-old"]},{"enonce":"Clara a payé avec deux billets de 20 £. Combien la caissière lui rend-elle d’après le ticket ?","aide":"Additionne les quatre prix, puis retire le total de 40.","type":"nombre","unite":"£"},{"enonce":"Pourquoi dit-on « a pair of gloves » avec *of* ?","aide":"Pense à *a piece of advice* et à *a cup of tea*.","type":"choix","options":[{"id":"a","texte":"Parce qu’on compte une quantité d’objets"},{"id":"b","texte":"Parce que pair est toujours un verbe"},{"id":"c","texte":"Parce que le premier nom prend toujours of"},{"id":"d","texte":"Parce que gloves est un adjectif composé"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5","m9","m15"]},"explication":"On écrit **ten-year-old**, **toy shop** et **two-hour trip** : l’élément qui précise reste au singulier."},{"cle":{"type":"zone","ids":["z3"]},"explication":"**a children’s book** est un livre pour enfants : *children’s* joue le rôle d’un adjectif."},{"cle":{"type":"trous","trous":[["ten year old"],["two hour"]]},"affichage":"ten-year-old · two-hour","explication":"**a ten-year-old girl**, **a two-hour trip** : pas de -s dans l’adjectif composé, mais *a trip of two hours* au pluriel."},{"cle":{"type":"nombre","valeur":6,"tolerance":0},"affichage":"6 £","explication":"8 + 5 + 6 + 15 = 34 £ ; 40 − 34 = **6 £** rendus."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Nom of nom** exprime une quantité ou un contenu : *a pair of gloves, a piece of advice*."}]$ex$::jsonb),
