  ('dd99cc2c-56ad-5449-b28f-86b0725d794d'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le week-end de la 2de B","competence":"lire-graphique","situation":"Le professeur d’anglais demande à sa classe de 30 élèves quelle est leur activité préférée du week-end. Il écrit les résultats au tableau.","documents":[{"id":"weekend","type":"graphique","forme":"barres","titre":"Favourite weekend activity (30 students)","categories":["Sport","Video games","Reading","Cinema"],"series":[{"nom":"Students","valeurs":[15,9,4,2],"teinte":"violet"}],"axeY":{"titre":"Students","min":0,"max":16,"pas":2},"valeurs":false,"source":"Chiffres inventés pour l’exercice"}],"questions":[{"enonce":"Touche l’activité dont on peut dire : « *Half of the students* prefer it ».","aide":"La moitié de 30, c’est 15.","type":"zone","document":"weekend","multiple":false},{"enonce":"Quelle phrase sur les jeux vidéo est vraie ?","aide":"9 élèves sur 30 : ni la plupart, ni tous, ni aucun.","type":"choix","options":[{"id":"a","texte":"All of the students prefer video games."},{"id":"b","texte":"Most of the students prefer video games."},{"id":"c","texte":"None of the students prefer video games."},{"id":"d","texte":"Some of the students prefer video games."}],"multiple":false},{"enonce":"Le professeur dit : « Half of ___ prefer sport. » Complète.","aide":"Après *of*, un pronom est toujours un complément.","type":"trous","segments":["Half of ",0," prefer sport."],"banque":["ourselves","us","our","we"]},{"enonce":"Choisis le bon verbe.","aide":"*Homework* est indénombrable : il n’a pas de pluriel.","type":"trous","segments":["Most of the homework ",0," done."],"banque":["was","were","have","are"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k0"]},"explication":"**Sport** : 15 élèves sur 30, la moitié exactement."},{"cle":{"type":"choix","ids":["d"]},"explication":"9 sur 30 : **some of the students** (certains). *Most* demanderait plus de la moitié."},{"cle":{"type":"trous","trous":[["us"]]},"affichage":"us","explication":"**Half of us** : après *of*, le pronom est complément (*us, them*), jamais *we*."},{"cle":{"type":"trous","trous":[["was"]]},"affichage":"was","explication":"**was** : le verbe s’accorde avec le nom (*homework*, indénombrable), pas avec *most*."}]$ex$::jsonb),
  ('dd99cc2c-56ad-5449-b28f-86b0725d794d'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le sondage sur les boissons","competence":"analyser-document","situation":"La classe a interrogé 20 élèves sur leur boisson préférée. Mais le brouillon du compte rendu contient des fautes de partitifs.","documents":[{"id":"sondage","type":"tableau","titre":"Favourite drink","colonnes":["Drink","Students (out of 20)"],"lignes":[["Water",12],["Juice",5],["Tea",3],["Coffee",0]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"},{"id":"brouillon","type":"texte","genre":"article","titre":"Draft report","blocs":["Here are the results of our drinks survey.","Most of students in our class prefer water. None of them don’t like coffee.","Some of we prefer juice or tea."],"source":"Brouillon écrit pour l’exercice, avec des erreurs"}],"questions":[{"enonce":"Touche les trois erreurs du brouillon : un *of* en trop, une double négation et un mauvais pronom.","aide":"Sans déterminant on parle en général ; *none* contient déjà la négation ; après *of*, le pronom est complément.","type":"zone","document":"brouillon","multiple":true},{"enonce":"Quelle phrase correspond au tableau ?","aide":"12 sur 20 : plus de la moitié.","type":"choix","options":[{"id":"a","texte":"Most of the students prefer water."},{"id":"b","texte":"Half of the students prefer juice."},{"id":"c","texte":"All of the students drink coffee."},{"id":"d","texte":"None of the students drink tea."}],"multiple":false},{"enonce":"Complète la phrase.","aide":"Le tableau indique 0.","type":"trous","segments":[0," of the students prefer coffee: the number in the table is zero."],"banque":["Most","None","Half","Both"]},{"enonce":"Relie chaque expression à sa traduction.","aide":"Après *of*, un pronom désigne un groupe précis.","type":"association","gauche":[{"id":"g0","texte":"Most of us"},{"id":"g1","texte":"None of them"},{"id":"g2","texte":"Both of us"},{"id":"g3","texte":"Half of the class"}],"droite":[{"id":"d0","texte":"Nous deux"},{"id":"d1","texte":"La moitié de la classe"},{"id":"d2","texte":"La plupart d’entre nous"},{"id":"d3","texte":"Aucun d’eux"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9","m19","m24"]},"explication":"**Most students** (pas de *of* en général), **None of them like** (négation déjà dans *none*), **Some of us** (jamais *of we*)."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Most of the students prefer water** (12/20). Le jus ne fait pas la moitié, 3 élèves boivent du thé et personne ne préfère le café."},{"cle":{"type":"trous","trous":[["none"]]},"affichage":"none","explication":"**None of the students** : *none* = aucun, la négation est déjà dans le mot."},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g0":"d2","g1":"d3"}},"explication":"**Most of us** = la plupart d’entre nous, **none of them** = aucun d’eux, **both of us** = nous deux, **half of the class** = la moitié de la classe."}]$ex$::jsonb),
  ('0e158099-eb14-5afa-811b-414fd78f899e'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les réponses de Tom","competence":"comprendre-langue","situation":"Mia pose des questions à Tom sur le sport. Regarde comment il répond : en anglais, c’est l’auxiliaire qui fait le travail.","documents":[{"id":"tennis","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Mia","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mia","texte":"Do you play tennis?"},{"qui":"Tom","texte":"Yes, I do."},{"qui":"Mia","texte":"Can your brother play too?"},{"qui":"Tom","texte":"No, he can’t."},{"qui":"Mia","texte":"Are your parents at home?"},{"qui":"Tom","texte":"Yes, they are."},{"qui":"Mia","texte":"Did you see the match yesterday?"},{"qui":"Tom","texte":"No, I didn’t."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les quatre auxiliaires que Tom utilise pour répondre.","aide":"Chaque réponse de Tom reprend l’auxiliaire de la question de Mia.","type":"zone","document":"tennis","multiple":true},{"enonce":"Mia demande : « Are you in the tennis club? » Tom répond oui. Quelle réponse est correcte ?","aide":"Dans une réponse affirmative courte, on ne contracte jamais.","type":"choix","options":[{"id":"a","texte":"Yes, I’m."},{"id":"b","texte":"Yes, I do."},{"id":"c","texte":"Yes, I am."},{"id":"d","texte":"Yes, am I."}],"multiple":false},{"enonce":"Mia demande : « Does your sister play tennis? » Tom répond oui. Complète sa réponse.","aide":"Reprends l’auxiliaire de la question de Mia.","type":"trous","segments":["Yes, she ",0,"."],"banque":["do","is","does","can"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6","m14","m22","m31"]},"explication":"Tom répond avec **do, can’t, are, didn’t** : l’auxiliaire de chaque question."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Yes, I am.** : on reprend l’auxiliaire *be* de la question, sans contraction."},{"cle":{"type":"trous","trous":[["does"]]},"affichage":"does","explication":"**Yes, she does.** : la question commençait par *Does*, la réponse reprend *does*."}]$ex$::jsonb),
  ('0e158099-eb14-5afa-811b-414fd78f899e'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"À la cantine avec Ruby et Sam","competence":"manier-langue","situation":"Ruby et Sam déjeunent à la cantine. Ils ne cessent de se répondre par « moi aussi » ou « moi non plus ».","documents":[{"id":"cantine","type":"dialogue","modele":"sms","titre":"At the canteen","participants":[{"nom":"Ruby","emoji":"👧","cote":"gauche"},{"nom":"Sam","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Ruby","texte":"I’m hungry!"},{"qui":"Sam","texte":"So am I!"},{"qui":"Ruby","texte":"I don’t like fish."},{"qui":"Sam","texte":"Neither do I."},{"qui":"Ruby","texte":"I’ve forgotten my wallet."},{"qui":"Sam","texte":"Have you? I can’t lend you any money!"}],"source":"Dialogue écrit pour l’exercice"}],"questions":[{"enonce":"Touche la réplique de Sam qui veut dire « moi non plus ».","aide":"Elle suit une phrase négative et commence par *Neither* ou *Nor*.","type":"zone","document":"cantine","multiple":true},{"enonce":"Touche la réplique de Sam qui exprime seulement la surprise ou l’intérêt (« Ah bon ? »).","aide":"Cette réplique est une petite question qui reprend l’auxiliaire de la phrase de Ruby.","type":"zone","document":"cantine","multiple":true},{"enonce":"Relie chaque phrase à la bonne réponse « moi aussi » ou « moi non plus ».","aide":"L’auxiliaire se choisit sur la phrase de départ : *be*, *do*, *have*…","type":"association","gauche":[{"id":"g0","texte":"I’m tired."},{"id":"g1","texte":"I don’t like coffee."},{"id":"g2","texte":"I’ve lost my keys."},{"id":"g3","texte":"We didn’t win."}],"droite":[{"id":"d0","texte":"So have I."},{"id":"d1","texte":"Neither did we."},{"id":"d2","texte":"Neither do I."},{"id":"d3","texte":"So am I."}]},{"enonce":"Ruby dit : « I was late. » Sam répond « moi aussi ». Complète.","aide":"Reprends l’auxiliaire de « I was late ».","type":"trous","segments":["So ",0," I."],"banque":["was","am","did","were"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9","m10","m11"]},"explication":"**Neither do I** : accord avec une phrase négative (*I don’t like fish*)."},{"cle":{"type":"zone","ids":["m16","m17"]},"explication":"**Have you?** reprend l’auxiliaire de *I’ve forgotten* : c’est une réaction, pas un accord."},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g1":"d2","g0":"d3"}},"explication":"Phrase positive : **so + auxiliaire + sujet**. Phrase négative : **neither + auxiliaire + sujet**."},{"cle":{"type":"trous","trous":[["was"]]},"affichage":"was","explication":"**So was I.** : la phrase de départ contient *was*, donc la réponse aussi."}]$ex$::jsonb),
  ('0e158099-eb14-5afa-811b-414fd78f899e'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"L’invitation de Max","competence":"argumenter","situation":"Nora et Ben parlent de la fête de Max. Un tableau montre les réponses reçues. Pour répondre juste, il faut reprendre le bon auxiliaire.","documents":[{"id":"fete","type":"dialogue","modele":"sms","titre":"About Max’s party","participants":[{"nom":"Nora","emoji":"👧","cote":"gauche"},{"nom":"Ben","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Nora","texte":"I don’t like big parties."},{"qui":"Ben","texte":"I do. They’re fun!"},{"qui":"Nora","texte":"Neither does my brother, but Max is his friend, so he’ll come."},{"qui":"Ben","texte":"Is Max’s sister coming too?"},{"qui":"Nora","texte":"I think so."},{"qui":"Ben","texte":"And will Lily come?"},{"qui":"Nora","texte":"I hope not. She was rude to me last week."}],"source":"Dialogue écrit pour l’exercice"},{"id":"reponses","type":"tableau","titre":"Max’s party: who is coming?","colonnes":["Guest","Answer"],"lignes":[["Max’s sister","Yes"],["Lily","No"],["Ben","Yes"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche la réplique de Ben qui exprime un désaccord (« Moi, si »).","aide":"Ben garde le sujet devant l’auxiliaire et inverse la polarité de la phrase de Nora.","type":"zone","document":"fete","multiple":true},{"enonce":"Que veut dire « Neither does my brother » ?","aide":"*Neither* répond à une phrase négative : c’est « moi non plus ».","type":"choix","options":[{"id":"a","texte":"Mon frère ne connaît personne là-bas"},{"id":"b","texte":"Mon frère n’est jamais invité chez eux"},{"id":"c","texte":"Mon frère n’aime pas ça non plus"},{"id":"d","texte":"Mon frère adore ces grandes fêtes"}],"multiple":false},{"enonce":"Nora ne veut pas que Lily vienne. Complète sa réponse.","aide":"Pour dire « j’espère que non », on remplace la proposition par un seul petit mot négatif.","type":"trous","segments":["I hope ",0,"."],"banque":["no","so","not","never"]},{"enonce":"Ben demande si la sœur de Max vient. Nora veut dire « hélas oui ». Que répond-elle ?","aide":"Il y a un mot pour « hélas » et un mot pour « oui ».","type":"choix","options":[{"id":"a","texte":"I’m afraid so."},{"id":"b","texte":"I hope so."},{"id":"c","texte":"I don’t think so."},{"id":"d","texte":"I’m afraid not."}],"multiple":false},{"enonce":"Réponds aux deux questions d’après le tableau.","aide":"La question commence par *is* : on garde *is*, en négatif ou en positif.","type":"trous","segments":["Is Lily coming? No, she ",0,". Is Max’s sister coming? Yes, she ",1,"."],"banque":["isn’t","does","is","doesn’t"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5","m6"]},"explication":"**I do** : Nora dit *I don’t like…*, Ben la contredit en gardant le sujet devant l’auxiliaire."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Neither does my brother** = lui non plus (il n’aime pas les grandes fêtes non plus)."},{"cle":{"type":"trous","trous":[["not"]]},"affichage":"not","explication":"**I hope not.** = j’espère que non ; *I hope so* = j’espère que oui."},{"cle":{"type":"choix","ids":["a"]},"explication":"**I’m afraid so.** = hélas oui ; *I’m afraid not* = hélas non."},{"cle":{"type":"trous","trous":[["isn t"],["is"]]},"affichage":"isn’t · is","explication":"**No, she isn’t.** (Lily : No) et **Yes, she is.** (la sœur de Max : Yes), sans contraction à l’affirmatif."}]$ex$::jsonb),
  ('3e702b92-f09f-59c2-8b97-33fe9de085e6'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"L’avis sur la cantine","competence":"analyser-texte","situation":"Un élève donne son opinion sur la cantine. Les connecteurs lui servent de panneaux pour guider le lecteur.","documents":[{"id":"cantine","type":"texte","genre":"article","titre":"Our canteen","blocs":["First of all, our canteen is cheap. Moreover, the food is healthy. However, the queues are long, so many students bring a lunch box. To sum up, the canteen is good but too crowded."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche le connecteur qui AJOUTE une idée à la précédente.","aide":"Il vient après « cheap » et il apporte un second point positif.","type":"zone","document":"cantine","multiple":false},{"enonce":"Touche le connecteur qui OPPOSE une idée aux précédentes.","aide":"Après deux points positifs, la phrase suivante apporte un défaut.","type":"zone","document":"cantine","multiple":false},{"enonce":"Relie chaque connecteur à son rôle.","aide":"Demande-toi : j’ajoute, j’oppose, je conclus ou j’annonce une conséquence ?","type":"association","gauche":[{"id":"g0","texte":"moreover"},{"id":"g1","texte":"however"},{"id":"g2","texte":"so"},{"id":"g3","texte":"to sum up"}],"droite":[{"id":"d0","texte":"annoncer une conséquence"},{"id":"d1","texte":"ajouter une idée"},{"id":"d2","texte":"conclure"},{"id":"d3","texte":"opposer deux idées"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7"]},"explication":"**Moreover** = de plus : il ajoute un argument dans le même sens."},{"cle":{"type":"zone","ids":["m12"]},"explication":"**However** = cependant : il introduit une opposition."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g3":"d2","g1":"d3"}},"explication":"**moreover** ajoute, **however** oppose, **so** annonce une conséquence, **to sum up** conclut."}]$ex$::jsonb),
  ('3e702b92-f09f-59c2-8b97-33fe9de085e6'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Faut-il porter l’uniforme ?","competence":"argumenter","situation":"Dans le journal du lycée, Hana donne les arguments pour et contre l’uniforme. Observe comment ses connecteurs enchaînent ses idées.","documents":[{"id":"uniforme","type":"texte","genre":"article","titre":"Should students wear a uniform?","blocs":["First of all, a uniform saves time in the morning. Moreover, it is cheaper than fashionable clothes. However, many students say it is boring, so some schools let them choose a colour. Sports clothes, for instance, are often chosen by the students. To sum up, there are good arguments on both sides."],"source":"Article écrit pour l’exercice"}],"questions":[{"enonce":"Touche le connecteur qui annonce la conclusion de l’article.","aide":"C’est la dernière phrase du texte.","type":"zone","document":"uniforme","multiple":true},{"enonce":"Touche le connecteur qui introduit un exemple.","aide":"Il est entre virgules, juste après « Sports clothes ».","type":"zone","document":"uniforme","multiple":true},{"enonce":"Range chaque phrase selon le rôle de son connecteur.","aide":"Demande-toi si la phrase ajoute un argument, s’oppose à la précédente ou en tire une conséquence.","type":"categories","categories":[{"id":"c0","texte":"Ajouter"},{"id":"c1","texte":"Opposer"},{"id":"c2","texte":"Conséquence"}],"items":[{"id":"i0","texte":"However, it is slow."},{"id":"i1","texte":"Besides, it is fun."},{"id":"i2","texte":"It was late, so we went home."},{"id":"i3","texte":"Consequently, the shop closed."},{"id":"i4","texte":"Moreover, it is cheap."},{"id":"i5","texte":"Yet, he failed."}]},{"enonce":"Complète avec le connecteur qui convient.","aide":"Le deuxième morceau s’oppose au premier : un film long, mais bon.","type":"trous","segments":["The film was long, ",0," it was very good."],"banque":["finally","such as","so","yet"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m42","m43","m44"]},"explication":"**To sum up** = pour conclure : il résume l’ensemble de l’article."},{"cle":{"type":"zone","ids":["m34","m35"]},"explication":"**for instance** = par exemple : il illustre l’idée avec un cas précis."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c2","i3":"c2","i4":"c0","i5":"c1"}},"explication":"*Moreover* et *besides* ajoutent ; *however* et *yet* opposent ; *so* et *consequently* annoncent une conséquence."},{"cle":{"type":"trous","trous":[["yet"]]},"affichage":"yet","explication":"**yet** = pourtant : il oppose « long » et « very good »."}]$ex$::jsonb),
  ('3e702b92-f09f-59c2-8b97-33fe9de085e6'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le brouillon sur les téléphones en classe","competence":"analyser-document","situation":"Une élève a écrit un brouillon sur l’usage du téléphone au lycée, avec un sondage à l’appui. Ses connecteurs ne sont pas tous bien choisis.","documents":[{"id":"brouillon","type":"texte","genre":"article","titre":"Phones in class: first draft","blocs":["In a first time, phones help students find information quickly.","Moreover, they can be a distraction in class, so many teachers ban them.","At last, schools need clear rules."],"source":"Brouillon écrit pour l’exercice, avec des erreurs"},{"id":"sondage","type":"graphique","forme":"barres","titre":"Are phones useful in class? (100 students)","categories":["Yes","No"],"series":[{"nom":"Students","valeurs":[62,38],"teinte":"turquoise"}],"axeY":{"titre":"Students","min":0,"max":70,"pas":10},"valeurs":false,"source":"Chiffres inventés pour l’exercice"}],"questions":[{"enonce":"Touche les trois connecteurs mal choisis : un calque du français, un connecteur qui AJOUTE alors qu’il faut OPPOSER, et un faux ami pour conclure.","aide":"Une idée négative après deux idées positives demande un connecteur d’opposition.","type":"zone","document":"brouillon","multiple":true},{"enonce":"Relie chaque connecteur fautif à sa correction.","aide":"*Actually* ne veut jamais dire « actuellement ».","type":"association","gauche":[{"id":"g0","texte":"In a first time"},{"id":"g1","texte":"Moreover (pour opposer)"},{"id":"g2","texte":"At last (pour finir)"},{"id":"g3","texte":"Actually (= actuellement)"}],"droite":[{"id":"d0","texte":"Currently"},{"id":"d1","texte":"First of all"},{"id":"d2","texte":"However"},{"id":"d3","texte":"Finally"}]},{"enonce":"D’après le graphique, complète avec le bon connecteur.","aide":"Les deux nombres vont en sens contraire.","type":"trous","segments":["62 students say yes. ",0,", 38 say no."],"banque":["Moreover","For example","Finally","However"]},{"enonce":"Combien d’élèves de plus disent « Yes » que « No » ?","aide":"Lis les deux barres, puis soustrais.","type":"nombre"},{"enonce":"Quelle conclusion correspond au graphique ?","aide":"62 % d’élèves disent « oui » : c’est la majorité.","type":"choix","options":[{"id":"a","texte":"To sum up, phones are useful because they are expensive."},{"id":"b","texte":"To sum up, no student finds phones useful at all."},{"id":"c","texte":"To sum up, half of the students want to ban phones."},{"id":"d","texte":"To sum up, most students find phones useful, but schools need rules."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0","m1","m2","m3","m10","m23","m24"]},"explication":"**In a first time** (calque : *first of all*), **Moreover** (à remplacer par *However*) et **At last** (soulagement, pas « en dernier lieu » : *finally*)."},{"cle":{"type":"association","paires":{"g3":"d0","g0":"d1","g1":"d2","g2":"d3"}},"explication":"*First of all* = d’abord, *however* oppose, *finally* clôt une liste, et *currently* ou *nowadays* = actuellement."},{"cle":{"type":"trous","trous":[["however"]]},"affichage":"however","explication":"**However** : il oppose les 62 « oui » aux 38 « non »."},{"cle":{"type":"nombre","valeur":24,"tolerance":0},"affichage":"24","explication":"62 − 38 = **24** élèves de plus."},{"cle":{"type":"choix","ids":["d"]},"explication":"62 sur 100 : **most students** trouvent les téléphones utiles ; « To sum up » conclut bien."}]$ex$::jsonb),
  ('fa8b32a2-289b-507d-98f7-01a8496951e8'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Une carte postale de Londres","competence":"comprendre-langue","situation":"Léa passe quelques jours à Londres et écrit une carte postale à son ami Sam. Observe les petits mots de lieu.","documents":[{"id":"carte","type":"texte","genre":"lettre","titre":"Postcard","blocs":["Hi Sam! I’m in London with my aunt. Our hotel is on Baker Street, and this afternoon we are going to the Science Museum."],"source":"Carte écrite pour l’exercice"}],"questions":[{"enonce":"Touche la préposition qui accompagne le nom d’une ville.","aide":"Une ville est vue comme un grand espace dans lequel on se trouve.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche la préposition qui accompagne le nom d’une rue.","aide":"Elle évoque une ligne, une surface.","type":"zone","document":"carte","multiple":false},{"enonce":"Relie chaque préposition à la manière de voir le lieu.","aide":"Pense à *in the kitchen*, *on the table*, *at the station*.","type":"association","gauche":[{"id":"g0","texte":"in"},{"id":"g1","texte":"on"},{"id":"g2","texte":"at"}],"droite":[{"id":"d0","texte":"une surface ou une ligne"},{"id":"d1","texte":"un volume ou une grande zone"},{"id":"d2","texte":"un point ou un lieu d’activité"}]},{"enonce":"Complète la phrase.","aide":"La gare est vue comme un point de rendez-vous.","type":"trous","segments":["Tomorrow I will wait for you ",0," the station."],"banque":["on","at","into","in"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3"]},"explication":"**in** : on dit *in London*, *in Paris*, *in France*."},{"cle":{"type":"zone","ids":["m11"]},"explication":"**on** : *on Baker Street* (*in* aussi en anglais britannique, mais *on* est le choix courant et américain)."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"**in** = volume, **on** = surface, **at** = point : trois façons de se représenter un lieu."},{"cle":{"type":"trous","trous":[["at"]]},"affichage":"at","explication":"**at the station** : un lieu d’activité ou un point précis se dit avec *at*."}]$ex$::jsonb),
