  ('84e53897-195a-5d1b-a022-f2d4e6b71593'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le carnet de recherche d’Ambre","competence":"lire-tableau","situation":"Ambre prépare un projet sur la disparition. Elle tient un carnet de recherche : essais, références, intentions. Le jury lira ce carnet avant même de regarder sa production.","documents":[{"id":"carnet","type":"tableau","titre":"Le carnet d’Ambre","colonnes":["Date","Entrée du carnet"],"lignes":[["3 oct.","Intention : « je veux rendre visible la disparition »"],["10 oct.","Essai 1 raté : encre trop diluée, le papier gondole"],["17 oct.","Référence annotée : une affiche déchirée vue au musée"],["24 oct.","Essai 2 : couches de papier calque, la forme s’efface"]],"enteteLignes":true}],"questions":[{"enonce":"Touche **l’entrée qui formule l’intention** du projet.","aide":"Une intention s’écrit comme une phrase : « je veux… ».","type":"zone","document":"carnet","multiple":false},{"enonce":"Touche **l’essai raté**.","aide":"Cherche l’entrée où quelque chose n’a pas fonctionné.","type":"zone","document":"carnet","multiple":false},{"enonce":"Combien de jours séparent l’intention de l’essai 2 ?","aide":"Lis les deux dates dans la première colonne, puis soustrais.","type":"nombre","unite":"jours"},{"enonce":"Relie chaque élément du carnet à ce qu’il prouve au jury.","aide":"Le carnet est une preuve : chaque trace montre un aspect de la démarche.","type":"association","gauche":[{"id":"g0","texte":"Des croquis et des variantes"},{"id":"g1","texte":"Des essais ratés, datés"},{"id":"g2","texte":"Des références annotées"},{"id":"g3","texte":"Des notes d’intention"}],"droite":[{"id":"d0","texte":"Que des choix ont été écartés"},{"id":"d1","texte":"Que le travail se situe"},{"id":"d2","texte":"Que la démarche est consciente"},{"id":"d3","texte":"Que la recherche a eu lieu"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1"]},"explication":"L’entrée du **3 octobre** formule l’intention : « je veux rendre visible la disparition ». C’est une phrase, pas un simple thème."},{"cle":{"type":"zone","ids":["r1c1"]},"explication":"L’**essai 1** a raté (encre trop diluée). Il reste dans le carnet : un échec daté prouve que la recherche a eu lieu."},{"cle":{"type":"nombre","valeur":21,"tolerance":0},"affichage":"21 jours","explication":"Du 3 octobre au 24 octobre : 24 − 3 = **21 jours**."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g3":"d2","g1":"d3"}},"explication":"**Croquis** : des choix écartés ; **essais ratés** : la recherche a eu lieu ; **références** : le travail se situe ; **notes d’intention** : la démarche est consciente."}]$ex$::jsonb),
  ('84e53897-195a-5d1b-a022-f2d4e6b71593'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La note d’intention de Malik","competence":"analyser-document","situation":"Malik, en seconde, présente une installation. Sa professeure lui demande de distinguer, dans sa note d’intention, le thème, l’intention et la consigne reçue, puis de nommer sa relation à une référence.","documents":[{"id":"note","type":"fiche","modele":"panneau","titre":"Note d’intention","entete":"Sous la table","sousTitre":"Malik, classe de seconde","emoji":"🪑","lignes":[{"texte":"Thème : le sentiment d’être de trop.","id":"z1"},{"texte":"Je veux que le spectateur hésite avant de s’asseoir.","id":"z2"},{"texte":"Consigne reçue : une installation de 2 m² au plus.","id":"z3"},{"separateur":true},{"texte":"Référence : je reprends le dispositif d’une chaise-piège pour en renverser le sens : ici, c’est l’absence de chaise qui invite.","id":"z4"}],"pied":"Note imaginée pour l’exercice"}],"questions":[{"enonce":"Touche **la ligne qui formule une intention** (et pas seulement un thème).","aide":"Une intention dit ce que l’on veut produire sur le spectateur.","type":"zone","document":"note","multiple":false},{"enonce":"Malik reprend un dispositif pour en renverser le sens. Touche **la ligne où il contredit sa référence**.","aide":"Cherche la ligne qui parle d’un dispositif repris.","type":"zone","document":"note","multiple":false},{"enonce":"Range chaque phrase : est-ce un thème, une intention ou une consigne ?","aide":"Un thème est un sujet ; une intention commence par « je veux » ; une consigne vient de l’extérieur.","type":"categories","categories":[{"id":"c0","texte":"Un thème"},{"id":"c1","texte":"Une intention"},{"id":"c2","texte":"Une consigne"}],"items":[{"id":"i0","texte":"Je veux que l’on ose toucher l’œuvre"},{"id":"i1","texte":"Je veux que le spectateur doute de ce qu’il voit"},{"id":"i2","texte":"Le temps qui passe"},{"id":"i3","texte":"Utiliser uniquement du carton"},{"id":"i4","texte":"Faire une sculpture de moins d’un mètre"},{"id":"i5","texte":"L’abandon"}]},{"enonce":"Laquelle de ces formulations est une vraie problématique ?","aide":"Une problématique admet plusieurs réponses plastiques ; une consigne n’en admet qu’une.","type":"choix","options":[{"id":"a","texte":"Dessiner une table et une chaise dans une pièce vide"},{"id":"b","texte":"Comment peindre une chaise bleue de quarante centimètres ?"},{"id":"c","texte":"Comment faire hésiter le spectateur sans rien lui interdire ?"},{"id":"d","texte":"Réaliser une installation en carton sur le thème de la chaise"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"« Je veux que le spectateur hésite avant de s’asseoir » est une **intention** : elle dit l’effet recherché. Le thème, lui, se contente de nommer un sujet."},{"cle":{"type":"zone","ids":["z4"]},"explication":"Reprendre un dispositif pour **en renverser le sens**, c’est **contredire** une référence : une chaise-piège devient une absence de chaise qui invite."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c2","i4":"c2","i5":"c0"}},"explication":"Un **thème** nomme un sujet ; une **intention** dit l’effet voulu sur le spectateur ; une **consigne** est donnée par le professeur et fixe des contraintes."},{"cle":{"type":"choix","ids":["c"]},"explication":"Seule la première **admet plusieurs réponses plastiques** (matière, échelle, dispositif…). Les autres sont des consignes : une seule réponse est possible."}]$ex$::jsonb),
  ('84e53897-195a-5d1b-a022-f2d4e6b71593'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"L’accrochage de « Marée »","competence":"analyser-document","situation":"Malik prépare l’accrochage de son projet « Marée » : trois pièces dans une salle. Son carnet montre que son travail a bougé. Il doit décider où mettre quoi, et comment défendre le changement.","documents":[{"id":"carnet","type":"tableau","titre":"Le carnet de Malik","colonnes":["Date","Entrée du carnet"],"lignes":[["2 nov.","Intention : faire sentir qu’une marée efface tout"],["9 nov.","Essai 1 : encre sur papier, trop net, l’effacement ne se voit pas"],["16 nov.","Essai 2 : sable au sol, les pas des visiteurs effacent les motifs. La pièce ne montre plus l’effacement : elle le fait vivre"],["23 nov.","Décision : la pièce au sol devient le cœur de l’accrochage"]],"enteteLignes":true},{"id":"plan","type":"schema","titre":"Plan de la salle","largeur":320,"hauteur":250,"elements":[{"forme":"rect","x":30,"y":20,"l":260,"h":170,"teinte":"gris","motif":"clair"},{"forme":"rect","x":140,"y":186,"l":40,"h":8,"teinte":"blanc","motif":"plein"},{"forme":"rect","x":90,"y":26,"l":140,"h":12,"teinte":"bleu","motif":"plein","id":"z1","zone":true},{"forme":"texte","x":160,"y":58,"texte":"A · grand tissu au mur du fond","taille":"petit","ancre":"milieu"},{"forme":"rect","x":34,"y":70,"l":10,"h":90,"teinte":"brun","motif":"plein","id":"z2","zone":true},{"forme":"texte","x":52,"y":118,"texte":"B · petits cadres","taille":"petit","ancre":"debut"},{"forme":"rect","x":190,"y":100,"l":90,"h":70,"teinte":"sable","motif":"points","id":"z3","zone":true},{"forme":"texte","x":235,"y":138,"texte":"C · sable","taille":"petit","ancre":"milieu"},{"forme":"ligne","de":[160,224],"a":[160,130],"fleche":"fin","style":"pointilles","teinte":"violet"},{"forme":"texte","x":160,"y":242,"texte":"Entrée du visiteur","taille":"petit","ancre":"milieu","italique":true}]}],"questions":[{"enonce":"Le visiteur entre par la porte et regarde droit devant lui. Touche **la première pièce qui s’offre à son regard**.","aide":"La flèche indique son chemin : regarde ce qui se trouve tout au bout, sur le mur du fond.","type":"zone","document":"plan","multiple":false},{"enonce":"Que montre l’entrée du 16 novembre ?","aide":"Compare l’intention du 2 novembre avec la phrase finale du 16 novembre.","type":"choix","options":[{"id":"a","texte":"L’intention se déplace : la pièce fait vivre l’effacement"},{"id":"b","texte":"L’essai est raté, il faut donc le cacher au jury"},{"id":"c","texte":"Le sable est une matière trop banale pour un projet"},{"id":"d","texte":"L’intention de départ est abandonnée sans aucune raison"}],"multiple":false},{"enonce":"Malik veut que les pas des visiteurs effacent les motifs. Touche **la pièce qui les invite à marcher dessus**.","aide":"Reprends l’essai 2 du carnet : quelle matière est posée au sol ?","type":"zone","document":"plan","multiple":false},{"enonce":"Complète la règle que Malik doit appliquer en présentant son travail.","aide":"Pense à ce que fait le jury : il lit des choix, pas des excuses.","type":"trous","segments":["Défendre son travail, c’est ",0," ses choix, jamais justifier les ",1,"."],"banque":["réussites","copier","expliciter","manques","cacher"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"Face à la porte, le visiteur voit d’abord **le grand tissu A**, accroché au mur du fond. L’accrochage fixe un ordre de lecture : il fait partie de l’œuvre."},{"cle":{"type":"choix","ids":["a"]},"explication":"En réalisant, Malik **déplace** son intention : au lieu de montrer l’effacement, la pièce le fait vivre. Un déplacement se **note** dans le carnet, il ne se cache pas."},{"cle":{"type":"zone","ids":["z3"]},"explication":"Le **sable C**, posé au sol, reçoit les pas des visiteurs : ce sont eux qui effacent les motifs. Le public devient acteur de la pièce."},{"cle":{"type":"trous","trous":[["expliciter","expliquer"],["manques","manque"]]},"affichage":"expliciter · manques","explication":"Défendre son travail, c’est **expliciter** ses choix ; on ne s’excuse pas de ses **manques**. Ici, Malik explique pourquoi le sable est devenu le cœur de l’accrochage."}]$ex$::jsonb),
