   $ex${"titre":"L’arrêté du maire et la loi","competence":"observer-schema","situation":"Le maire de la commune de Karim a pris un arrêté qui interdit les vélos sur la place du marché. Karim se demande si ce texte pèse autant qu’une loi : il observe la pyramide des normes de son cours.","documents":[{"id":"pyramide","type":"schema","titre":"La hiérarchie des normes","source":"Schéma simplifié pour l’exercice","largeur":390,"hauteur":266,"elements":[{"forme":"polygone","points":[[156,14],[224,14],[250,56],[130,56]],"teinte":"violet","motif":"clair","id":"z1","zone":true},{"forme":"texte","x":190,"y":40,"texte":"Constitution","ancre":"milieu","gras":true},{"forme":"texte","x":14,"y":40,"texte":"1","taille":"grand","gras":true},{"forme":"polygone","points":[[127,60],[253,60],[279,102],[101,102]],"teinte":"violet","motif":"clair","id":"z2","zone":true},{"forme":"texte","x":190,"y":86,"texte":"Traités et droit de l’UE","ancre":"milieu","gras":true},{"forme":"texte","x":14,"y":86,"texte":"2","taille":"grand","gras":true},{"forme":"polygone","points":[[99,106],[281,106],[307,148],[73,148]],"teinte":"violet","motif":"clair","id":"z3","zone":true},{"forme":"texte","x":190,"y":132,"texte":"Loi","ancre":"milieu","gras":true},{"forme":"texte","x":14,"y":132,"texte":"3","taille":"grand","gras":true},{"forme":"polygone","points":[[70,152],[310,152],[336,194],[44,194]],"teinte":"violet","motif":"clair","id":"z4","zone":true},{"forme":"texte","x":190,"y":178,"texte":"Décrets, arrêtés","ancre":"milieu","gras":true},{"forme":"texte","x":14,"y":178,"texte":"4","taille":"grand","gras":true},{"forme":"polygone","points":[[42,198],[338,198],[364,240],[16,240]],"teinte":"violet","motif":"clair","id":"z5","zone":true},{"forme":"texte","x":190,"y":224,"texte":"Contrats","ancre":"milieu","gras":true},{"forme":"texte","x":14,"y":224,"texte":"5","taille":"grand","gras":true},{"forme":"ligne","de":[370,236],"a":[370,20],"fleche":"fin","teinte":"encre"},{"forme":"texte","x":370,"y":252,"texte":"Rang le plus élevé en haut","taille":"petit","italique":true,"ancre":"fin"}]}],"questions":[{"enonce":"Touche le niveau de la pyramide où se range un arrêté du maire.","aide":"Un arrêté fait partie des règlements, avec les décrets.","type":"zone","document":"pyramide","multiple":false},{"enonce":"Combien de niveaux de la pyramide se trouvent au-dessus des décrets et arrêtés ?","aide":"Compte les étages situés plus haut que celui des règlements.","type":"nombre"},{"enonce":"Si l’arrêté du maire contredit une loi, que peut faire le juge ?","aide":"Regarde quelle norme est au-dessus de l’autre.","type":"choix","options":[{"id":"a","texte":"Le transmettre au Parlement pour qu’il devienne une loi"},{"id":"b","texte":"L’annuler, car la loi est au-dessus de lui"},{"id":"c","texte":"Le laisser s’appliquer, car il est plus récent"},{"id":"d","texte":"Le réécrire lui-même pour le rendre conforme"}],"multiple":false}]}$ex$::jsonb,
