  ('c3ba5e5b-b29c-50b5-b5cb-9e66d44134ba'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une semaine de pouvoirs autour des trottinettes","competence":"analyser-document","situation":"Pour son exposé d’EMC, Inès suit cinq décisions prises en une semaine à propos des trottinettes électriques. Elle veut savoir quel pouvoir agit chaque jour, et pourquoi il faut les séparer.","documents":[{"id":"semaine","type":"tableau","titre":"Cinq décisions de la semaine","source":"Situations écrites pour l’exercice","colonnes":["Jour","Décision"],"lignes":[["Lundi","L’Assemblée nationale adopte une loi sur la sécurité des trottinettes."],["Mardi","Le gouvernement publie le décret qui précise les règles de circulation."],["Mercredi","Un tribunal condamne un automobiliste qui a renversé un cycliste."],["Jeudi","Le Sénat vote à son tour le texte de loi."],["Vendredi","Un préfet fait appliquer le décret en contrôlant les loueurs."]],"enteteLignes":true},{"id":"montesquieu","type":"texte","genre":"source","titre":"Montesquieu, De l’esprit des lois (1748)","source":"Livre XI, chapitre 4","blocs":["Pour qu’on ne puisse abuser du pouvoir, il faut que, par la disposition des choses, le pouvoir arrête le pouvoir."]}],"questions":[{"enonce":"Touche les deux décisions prises par le pouvoir législatif.","aide":"Qui fait la loi ? Cherche les deux assemblées du Parlement.","type":"zone","document":"semaine","multiple":true},{"enonce":"Associe chaque jour au pouvoir qui agit.","aide":"Le législatif fait la loi, l’exécutif l’applique, le judiciaire la fait respecter.","type":"association","gauche":[{"id":"g0","texte":"Lundi : l’adoption de la loi"},{"id":"g1","texte":"Mardi : la publication du décret"},{"id":"g2","texte":"Mercredi : la condamnation"}],"droite":[{"id":"d0","texte":"Pouvoir exécutif"},{"id":"d1","texte":"Pouvoir législatif"},{"id":"d2","texte":"Pouvoir judiciaire"}]},{"enonce":"Touche le verbe par lequel Montesquieu dit ce que le pouvoir doit faire au pouvoir.","aide":"Le verbe est celui de la célèbre formule « … le pouvoir ».","type":"zone","document":"montesquieu","multiple":false},{"enonce":"Que risquerait-on si un seul organe faisait la loi, l’appliquait et jugeait ceux qui l’enfreignent ?","aide":"Pense à la phrase de Montesquieu : qui arrêterait ce pouvoir ?","type":"choix","options":[{"id":"a","texte":"L’arbitraire : plus personne ne limiterait ce pouvoir"},{"id":"b","texte":"Un ralentissement du vote des lois, faute de débat suffisant"},{"id":"c","texte":"Une multiplication des tribunaux dans chaque département"},{"id":"d","texte":"Une baisse du nombre d’élections organisées chaque année"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1","r3c1"]},"explication":"Le pouvoir **législatif** fait la loi : l’**Assemblée nationale** (lundi) et le **Sénat** (jeudi) appartiennent au Parlement."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"Le **législatif** fait la loi, l’**exécutif** l’applique (décret, préfet), le **judiciaire** la fait respecter (tribunal)."},{"cle":{"type":"zone","ids":["m18"]},"explication":"Pour Montesquieu, « il faut que le pouvoir **arrête** le pouvoir » : chacun limite les autres."},{"cle":{"type":"choix","ids":["a"]},"explication":"Sans séparation des pouvoirs, aucun organe ne limite les autres : c’est l’**arbitraire**, le contraire de l’État de droit."}]$ex$::jsonb),
  ('c3ba5e5b-b29c-50b5-b5cb-9e66d44134ba'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Un refus de salle devant le juge","competence":"argumenter","situation":"Le club de théâtre du lycée de Maya s’est vu refuser une salle municipale par le maire. Le tribunal administratif a été saisi. Maya lit la décision résumée, puis cherche à qui s’adresser dans d’autres situations.","documents":[{"id":"decision","type":"texte","genre":"source","titre":"Décision du tribunal administratif (résumé)","source":"Texte écrit pour l’exercice","blocs":["La commune de Valdor a refusé de prêter sa salle polyvalente au club de théâtre du lycée, au motif que le maire « n’aime pas ce genre de pièces ».","Le règlement municipal prévoit le prêt gratuit de la salle à toute association déclarée, sans condition d’opinion. Le tribunal juge que ce refus ne repose sur aucun motif prévu par ce règlement et annule la décision du maire."]},{"id":"cas","type":"tableau","titre":"Quatre situations","source":"Situations écrites pour l’exercice","colonnes":["Cas","Situation"],"lignes":[["A","Un habitant conteste un refus de permis de construire."],["B","Une personne estime qu’une loi déjà en vigueur viole la Constitution."],["C","Des juges rendent des décisions contradictoires sur le même texte de loi."],["D","Un citoyen estime que la France a violé ses droits fondamentaux."]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui dit ce que fait le tribunal de la décision du maire.","aide":"Le tribunal ne la modifie pas : il la fait disparaître.","type":"zone","document":"decision","multiple":false},{"enonce":"Remets dans l’ordre le raisonnement du juge.","aide":"Du texte applicable à la conclusion : règle, cas, constat, décision.","type":"ordre","items":[{"id":"a","texte":"La décision du maire est annulée"},{"id":"b","texte":"Le refus repose sur un goût du maire, qu’aucun texte ne prévoit"},{"id":"c","texte":"Le règlement prévoit le prêt de la salle à toute association déclarée"},{"id":"d","texte":"Le club de théâtre du lycée est une association déclarée"}]},{"enonce":"En quoi cette décision illustre-t-elle l’État de droit ?","aide":"Qui est tenu de respecter le règlement : les citoyens seulement, ou aussi le maire ?","type":"choix","options":[{"id":"a","texte":"La loi permet à chaque maire de choisir librement les spectacles accueillis"},{"id":"b","texte":"Le maire est lui aussi soumis aux règles, et un juge peut le contrôler"},{"id":"c","texte":"Le tribunal a remplacé le maire dans l’exercice de ses fonctions"},{"id":"d","texte":"Le maire garde le dernier mot sur l’usage de toutes les salles communales"}],"multiple":false},{"enonce":"Associe chaque situation du tableau à l’institution à qui s’adresser.","aide":"Relis la fonction de chaque gardien dans ton cours.","type":"association","gauche":[{"id":"g0","texte":"Cas A"},{"id":"g1","texte":"Cas B"},{"id":"g2","texte":"Cas C"},{"id":"g3","texte":"Cas D"}],"droite":[{"id":"d0","texte":"La Cour européenne des droits de l’homme, à Strasbourg"},{"id":"d1","texte":"La Cour de cassation, qui veille à l’interprétation du droit"},{"id":"d2","texte":"Le Conseil constitutionnel, par la QPC"},{"id":"d3","texte":"Le Conseil d’État, juge de l’administration"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m63"]},"explication":"Le tribunal **annule** la décision : une décision de l’administration contraire aux règles peut être annulée par le juge."},{"cle":{"type":"ordre","ids":["c","d","b","a"]},"explication":"Le juge part de la **règle** (le règlement), constate que le club y **entre**, que le refus ne s’appuie sur **aucun motif** prévu, puis **annule**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Gouvernants et gouvernés sont soumis au droit : le **maire** doit respecter le règlement et un **juge indépendant** peut annuler sa décision."},{"cle":{"type":"association","paires":{"g3":"d0","g2":"d1","g1":"d2","g0":"d3"}},"explication":"Conseil d’État : l’**administration** ; Conseil constitutionnel : la **QPC** ; Cour de cassation : l’**interprétation** du droit ; CEDH : la **violation** des droits fondamentaux."}]$ex$::jsonb),
  ('c30bf9d1-1f5f-542c-a395-2dc384c3a50d'::uuid, 1, 1, 5, 20, 3,
