  ('c30bf9d1-1f5f-542c-a395-2dc384c3a50d'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Chasse à l’erreur dans un exposé","competence":"analyser-document","situation":"Hugo envoie à Élise la fiche de son exposé sur la construction de l’État de droit. Élise sait qu’une de ses dates est fausse. Elle sort son cours pour la retrouver, puis range les textes par époque.","documents":[{"id":"sms","type":"dialogue","modele":"sms","source":"Messages écrits pour l’exercice","participants":[{"nom":"Hugo","emoji":"👦","cote":"gauche"},{"nom":"Élise","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Hugo","texte":"Voici ma fiche : l’habeas corpus date de 1215, la liberté d’association de 1901 et l’abolition de la peine de mort de 1981."},{"qui":"Élise","texte":"Relis ton cours : une de tes dates est fausse."}]},{"id":"cours","type":"tableau","titre":"Le cours d’Élise","source":"Dates tirées du cours","colonnes":["Date","Texte ou liberté"],"lignes":[["1215","Magna Carta"],["1679","Habeas corpus"],["1881","Liberté de la presse"],["1884","Liberté syndicale"],["1901","Liberté d’association"],["1905","Séparation des Églises et de l’État"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la date fausse dans le message d’Hugo.","aide":"L’une des trois dates correspond à un autre texte que celui qu’il cite.","type":"zone","document":"sms","multiple":false},{"enonce":"Dans le tableau, touche la case qui donne la bonne date de l’habeas corpus.","aide":"Cherche d’abord la ligne qui nomme l’habeas corpus.","type":"zone","document":"cours","multiple":false},{"enonce":"Combien d’années séparent la liberté syndicale de la liberté d’association ?","aide":"Lis les deux dates dans le tableau, puis soustrais.","type":"nombre"},{"enonce":"Range chaque texte dans la bonne époque.","aide":"Le XXe siècle commence en 1901.","type":"categories","categories":[{"id":"c0","texte":"Avant 1789"},{"id":"c1","texte":"XIXe siècle"},{"id":"c2","texte":"XXe siècle"}],"items":[{"id":"i0","texte":"Liberté de la presse"},{"id":"i1","texte":"Liberté d’association"},{"id":"i2","texte":"Liberté syndicale"},{"id":"i3","texte":"Magna Carta"},{"id":"i4","texte":"Habeas corpus"},{"id":"i5","texte":"Séparation des Églises et de l’État"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8"]},"explication":"**1215** est la date de la **Magna Carta** ; l’**habeas corpus** date de **1679**."},{"cle":{"type":"zone","ids":["r1c0"]},"explication":"La ligne « Habeas corpus » porte la date **1679**."},{"cle":{"type":"nombre","valeur":17,"tolerance":0},"affichage":"17","explication":"1901 − 1884 = **17 ans**."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c2","i2":"c1","i3":"c0","i4":"c0","i5":"c2"}},"explication":"Avant 1789 : Magna Carta et habeas corpus. XIXe siècle : 1881 et 1884. XXe siècle : **1901** (le XXe siècle commence en 1901) et **1905**."}]$ex$::jsonb),
  ('c30bf9d1-1f5f-542c-a395-2dc384c3a50d'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Des États légaux mais criminels","competence":"analyser-texte","situation":"Après 1945, on s’aperçoit que des États légaux ont commis des crimes. Pour son dossier, Sacha lit l’article 16 de la Déclaration de 1789 et suit la frise des garanties créées ensuite.","documents":[{"id":"art16","type":"texte","genre":"source","titre":"Déclaration des droits de l’homme et du citoyen, 1789","source":"Article 16","blocs":["Toute Société dans laquelle la garantie des Droits n’est pas assurée, ni la séparation des Pouvoirs déterminée, n’a point de Constitution."]},{"id":"frise2","type":"frise","titre":"Après 1945","source":"Dates tirées du cours","debut":1940,"fin":2020,"pas":10,"evenements":[{"id":"z1","date":1948,"nom":"DUDH"},{"id":"z2","date":1958,"nom":"Conseil constitutionnel"},{"id":"z3","date":1971,"nom":"Décision du Conseil"},{"id":"z4","date":2010,"nom":"QPC"}]}],"questions":[{"enonce":"Touche les deux mots qui désignent la seconde condition posée par l’article 16.","aide":"L’article en pose deux : la garantie des droits, puis une autre.","type":"zone","document":"art16","multiple":true},{"enonce":"Pourquoi la garantie des droits devient-elle internationale après 1945 ?","aide":"Le cours parle d’États « légaux mais criminels ».","type":"choix","options":[{"id":"a","texte":"Des États légaux avaient commis des crimes : respecter ses lois ne suffisait plus"},{"id":"b","texte":"Les Constitutions nationales venaient d’être supprimées dans tous les pays d’Europe"},{"id":"c","texte":"Les juges nationaux avaient cessé d’exister dans les pays qui avaient été en guerre"},{"id":"d","texte":"Les traités internationaux remplaçaient désormais toutes les lois nationales"}],"multiple":false},{"enonce":"Touche la date où le Conseil constitutionnel donne valeur constitutionnelle au Préambule, donc à la Déclaration de 1789.","aide":"Le Conseil est créé en 1958 ; cherche l’étape où il s’émancipe.","type":"zone","document":"frise2","multiple":false},{"enonce":"Combien d’années séparent la création du Conseil constitutionnel de sa décision qui donne valeur constitutionnelle au Préambule ?","aide":"Lis les deux dates sur la frise.","type":"nombre"},{"enonce":"Que permet cette décision de 1971 au Conseil constitutionnel ?","aide":"La Déclaration de 1789 devient une norme de rang constitutionnel.","type":"choix","options":[{"id":"a","texte":"Juger les litiges des citoyens avec l’administration"},{"id":"b","texte":"Censurer une loi contraire à la Déclaration de 1789"},{"id":"c","texte":"Voter lui-même les lois à la place du Parlement"},{"id":"d","texte":"Condamner la France devant la Cour de Strasbourg"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14","m16"]},"explication":"La seconde condition est la **séparation des pouvoirs** ; la première est la **garantie des droits**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Les crimes de régimes **légaux** ont montré qu’un État peut suivre ses propres lois et violer les droits : la garantie devient **internationale** (1948, 1950)."},{"cle":{"type":"zone","ids":["z3"]},"explication":"En **1971**, le Conseil constitutionnel donne valeur constitutionnelle au Préambule, donc à la **Déclaration de 1789**."},{"cle":{"type":"nombre","valeur":13,"tolerance":0},"affichage":"13","explication":"1971 − 1958 = **13 ans**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le Conseil peut **censurer** une loi qui viole la Déclaration de 1789 : elle fait partie du bloc de constitutionnalité."}]$ex$::jsonb),
  ('00ce64fb-084e-5285-93f2-e8883a782347'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Quatre phrases entendues au foyer","competence":"analyser-texte","situation":"Au foyer du lycée, Yanis entend plusieurs phrases sur la laïcité. Il voudrait savoir lesquelles sont justes avant de les répéter dans son exposé.","documents":[{"id":"phrases","type":"tableau","titre":"Quatre phrases entendues","source":"Phrases écrites pour l’exercice","colonnes":["N°","Phrase"],"lignes":[["1","La laïcité interdit de croire en une religion."],["2","La laïcité garantit la liberté de conscience."],["3","La laïcité vise une religion en particulier."],["4","L’État ne reconnaît, ne salarie ni ne subventionne aucun culte."]],"enteteLignes":true}],"questions":[{"enonce":"Touche les deux phrases fausses.","aide":"La laïcité garantit la liberté de croire et vaut pour toutes les religions.","type":"zone","document":"phrases","multiple":true},{"enonce":"Quel principe la loi de 1905 pose-t-elle en premier, dans son article 1er ?","aide":"L’ordre des articles compte : d’abord la liberté, ensuite la séparation.","type":"choix","options":[{"id":"a","texte":"La liberté de conscience et le libre exercice des cultes"},{"id":"b","texte":"La séparation des Églises et de l’État"},{"id":"c","texte":"L’interdiction des signes religieux à l’école"},{"id":"d","texte":"La neutralité des agents publics"}],"multiple":false},{"enonce":"Complète la définition.","aide":"Ce n’est pas une opinion sur la religion, mais une règle.","type":"trous","segments":["La laïcité est une règle d’",0," de l’État : elle garantit la liberté de ",1," et sépare l’État des ",2,"."],"banque":["cultes","opinion","organisation","conscience","dépense"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1","r2c1"]},"explication":"La laïcité **garantit** la liberté de conscience et vaut pour **toutes** les religions de la même façon : les phrases 1 et 3 sont fausses."},{"cle":{"type":"choix","ids":["a"]},"explication":"L’article 1er garantit la **liberté de conscience** et le libre exercice des cultes ; l’article 2 pose ensuite la **séparation**."},{"cle":{"type":"trous","trous":[["organisation"],["conscience"],["cultes"]]},"affichage":"organisation · conscience · cultes","explication":"La laïcité est une règle d’**organisation** de l’État : liberté de **conscience** et séparation de l’État et des **cultes**."}]$ex$::jsonb),
  ('00ce64fb-084e-5285-93f2-e8883a782347'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Qui doit rester neutre ?","competence":"analyser-document","situation":"Le CVL affiche dans le hall six situations de la vie quotidienne. Quentin doit dire, pour chacune, quelle règle de laïcité s’applique, en s’aidant du rappel des textes affiché à côté.","documents":[{"id":"situations","type":"tableau","titre":"Six situations","source":"Situations écrites pour l’exercice","colonnes":["N°","Situation"],"lignes":[["1","Une agente d’accueil de la préfecture reçoit le public."],["2","Un élève de seconde entre dans son lycée public."],["3","Un étudiant de 20 ans suit un cours à l’université."],["4","Une cliente fait ses courses dans une boulangerie."],["5","Un professeur de lycée public fait cours."],["6","Une collégienne arrive dans son collège public."]],"enteteLignes":true},{"id":"rappel","type":"fiche","modele":"affiche","entete":"Ce que disent les textes","sousTitre":"Rappel simplifié","emoji":"⚖️","lignes":[{"texte":"Loi du 15 mars 2004 : élèves des écoles, collèges et lycées publics","id":"z1"},{"texte":"Stricte neutralité des agents publics en service","id":"z2"},{"texte":"À l’université : des étudiants majeurs et libres","id":"z3"},{"texte":"Charte de la laïcité à l’école (2013)","id":"z4"}]}],"questions":[{"enonce":"Range chaque personne dans la bonne règle.","aide":"Distingue les agents publics, les élèves du public et les autres usagers.","type":"categories","categories":[{"id":"c0","texte":"Stricte neutralité"},{"id":"c1","texte":"Signes ostensibles interdits"},{"id":"c2","texte":"Liberté"}],"items":[{"id":"i0","texte":"La cliente de la boulangerie"},{"id":"i1","texte":"Le professeur du lycée public"},{"id":"i2","texte":"L’étudiant de 20 ans à l’université"},{"id":"i3","texte":"L’agente d’accueil de la préfecture"},{"id":"i4","texte":"L’élève de seconde du lycée public"},{"id":"i5","texte":"La collégienne du collège public"}]},{"enonce":"Touche la ligne du rappel qui s’applique à la situation 3.","aide":"La situation 3 se passe après le lycée.","type":"zone","document":"rappel","multiple":false},{"enonce":"Une cliente peut-elle porter un signe religieux dans la boulangerie (situation 4) ?","aide":"La loi de 2004 vise un lieu précis.","type":"choix","options":[{"id":"a","texte":"Non : la laïcité interdit tout signe religieux dans l’espace public"},{"id":"b","texte":"Non : la loi de 2004 s’applique dans tous les lieux ouverts au public"},{"id":"c","texte":"Oui : la neutralité s’impose à l’État et à ses agents, pas aux clients"},{"id":"d","texte":"Oui, mais seulement si le boulanger l’a autorisé par écrit"}],"multiple":false},{"enonce":"Parmi les six situations, combien soumettent la personne à une règle de neutralité ou d’interdiction ?","aide":"Compte les agents publics et les élèves du public.","type":"nombre"}]}$ex$::jsonb,
