   $ex${"titre":"Alsace-Moselle : pourquoi un régime à part ?","competence":"analyser-document","situation":"Julie vit à Strasbourg et Malik à Lyon. En préparant leur exposé commun, ils découvrent que le régime des cultes n’est pas le même chez eux, puis comparent la France à ses voisins.","documents":[{"id":"sms","type":"dialogue","modele":"sms","source":"Messages écrits pour l’exercice","participants":[{"nom":"Malik","emoji":"👦","cote":"gauche"},{"nom":"Julie","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Malik","texte":"La loi de 1905 vaut pour toute la France, non ?"},{"qui":"Julie","texte":"Chez nous, en Alsace-Moselle, le régime concordataire existe encore : en 1905, la région était allemande."}]},{"id":"europe","type":"tableau","titre":"Les cultes et l’État","source":"Informations simplifiées pour l’exercice","colonnes":["Pays","Rapport entre l’État et les cultes"],"lignes":[["France (métropole)","Séparation depuis 1905 : l’État ne reconnaît, ne salarie ni ne subventionne aucun culte"],["Alsace-Moselle","Régime concordataire maintenu"],["Danemark","Une Église luthérienne a le statut d’Église d’État"],["Allemagne","L’État collecte pour les Églises qui le demandent un impôt cultuel"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui explique pourquoi l’Alsace-Moselle n’a pas suivi la loi de 1905.","aide":"Quelle était la situation de la région à cette date ?","type":"zone","document":"sms","multiple":false},{"enonce":"Touche la ligne d’un pays où l’État collecte un impôt pour les Églises qui le demandent.","aide":"Cherche le mot « impôt ».","type":"zone","document":"europe","multiple":false},{"enonce":"Que montre ce tableau de la laïcité française ?","aide":"Compare la première ligne aux autres.","type":"choix","options":[{"id":"a","texte":"Qu’elle est la règle commune de tous les pays européens"},{"id":"b","texte":"Qu’elle interdit toute liberté religieuse aux citoyens"},{"id":"c","texte":"Qu’elle n’a jamais connu d’exception sur son territoire"},{"id":"d","texte":"Un cas particulier : d’autres démocraties financent des cultes"}],"multiple":false},{"enonce":"Quelles affirmations sont exactes ? (plusieurs réponses)","aide":"Relis le tableau et la discussion de Julie et Malik.","type":"choix","options":[{"id":"a","texte":"En France, l’Alsace-Moselle et la Guyane ont chacune un régime propre pour les cultes"},{"id":"b","texte":"Un pays qui reconnaît une Église d’État peut garantir la liberté religieuse"},{"id":"c","texte":"La loi de 1905 a été appliquée à l’Alsace-Moselle dès son adoption"},{"id":"d","texte":"Dans tous les pays démocratiques, l’État ne finance aucun culte"}],"multiple":true}]}$ex$::jsonb,
