  ('11f62154-d6e1-5fee-b539-bac2fad85fc5'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une marche pour le climat","competence":"analyser-document","situation":"Des lycéens de la ville d’Ambreuil organisent une marche pour le climat un samedi. Avant de lancer les invitations, ils vérifient avec leur professeur les formalités à accomplir.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","entete":"Marche pour le climat","sousTitre":"Affiche écrite pour l’exercice","emoji":"🌍","lignes":[{"texte":"Samedi, 14 h","id":"z1"},{"texte":"Départ place de la Mairie, arrivée au parc","id":"z2"},{"texte":"Déclaration déposée à la préfecture avant la marche","id":"z3"},{"texte":"Aucune autorisation demandée","id":"z4"}]}],"questions":[{"enonce":"Touche la ligne qui montre la formalité que la loi exige pour manifester.","aide":"Pour manifester, on déclare : cherche la ligne qui parle de la préfecture.","type":"zone","document":"affiche","multiple":false},{"enonce":"Les organisateurs n’ont demandé aucune autorisation. Est-ce un problème ?","aide":"Distingue « déclarer » et « demander l’autorisation ».","type":"choix","options":[{"id":"a","texte":"Oui : le maire doit signer l’affiche avant sa diffusion publique"},{"id":"b","texte":"Non : aucune formalité n’est jamais exigée, quel que soit le cortège"},{"id":"c","texte":"Oui : toute manifestation exige l’accord écrit du préfet du département"},{"id":"d","texte":"Non : une manifestation se déclare, elle n’est pas soumise à autorisation"}],"multiple":false},{"enonce":"Complète la liste des composantes de l’ordre public.","aide":"Elle protège les personnes, le calme et la santé.","type":"trous","segments":["L’ordre public comprend la ",0,", la ",1," et la ",2," publiques."],"banque":["salubrité","rentabilité","tranquillité","popularité","sécurité"]}]}$ex$::jsonb,
