  ('11f62154-d6e1-5fee-b539-bac2fad85fc5'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Trois arrêtés à passer au test","competence":"raisonner","situation":"Dans la ville de Roncel, le maire a signé trois arrêtés. Le CVL du lycée les examine un à un avec le test de proportionnalité, pour dire lesquels un juge risque d’annuler.","documents":[{"id":"arretes","type":"tableau","titre":"Trois arrêtés du maire","source":"Arrêtés écrits pour l’exercice","colonnes":["Arrêté","Contenu","Motif invoqué"],"lignes":[["A","Interdit toute manifestation, partout dans la commune, sans limite de durée","Éviter tout trouble"],["B","Interdit à tout cortège une rue précise samedi soir, jour d’un match où des bagarres sont annoncées","Prévenir des bagarres"],["C","Interdit la baignade dans un lac pendant deux jours après une pollution constatée","Protéger la santé"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la mesure générale et absolue, que le juge annulera presque toujours.","aide":"Cherche l’arrêté sans limite de lieu ni de durée.","type":"zone","document":"arretes","multiple":false},{"enonce":"Associe chaque critère du test à sa question.","aide":"Un critère parle du but, un du « moins sévère », un de l’excès.","type":"association","gauche":[{"id":"g0","texte":"Adaptée"},{"id":"g1","texte":"Nécessaire"},{"id":"g2","texte":"Proportionnée"}],"droite":[{"id":"d0","texte":"La mesure sert-elle bien le but invoqué ?"},{"id":"d1","texte":"L’atteinte est-elle excessive par rapport au bénéfice ?"},{"id":"d2","texte":"Une mesure moins sévère suffirait-elle ?"}]},{"enonce":"Qu’est-ce qui justifie l’arrêté B ?","aide":"Relis le contenu et le motif de l’arrêté B.","type":"choix","options":[{"id":"a","texte":"Le souhait de tout interdire par précaution"},{"id":"b","texte":"Un risque précis de trouble, limité à une rue et à une soirée"},{"id":"c","texte":"Le désaccord du maire avec le sujet de la manifestation"},{"id":"d","texte":"Le seul fait que le cortège gêne les automobilistes"}],"multiple":false},{"enonce":"Les organisateurs de la manifestation visée par l’arrêté A saisissent le juge du référé-liberté lundi à 9 h. Au plus tard, quand doit-il statuer ?","aide":"Le délai du référé-liberté est de 48 heures.","type":"choix","options":[{"id":"a","texte":"Jeudi à 9 h"},{"id":"b","texte":"Vendredi à 9 h"},{"id":"c","texte":"Mardi à 9 h"},{"id":"d","texte":"Mercredi à 9 h"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1"]},"explication":"Une interdiction **générale et absolue** est presque toujours annulée : ici, l’arrêté **A** interdit tout, partout, sans limite."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"**Adaptée** : sert-elle le but ? **Nécessaire** : une mesure moins sévère suffirait-elle ? **Proportionnée** : l’atteinte n’est-elle pas excessive ?"},{"cle":{"type":"choix","ids":["b"]},"explication":"L’interdiction est justifiée par un **risque précis de trouble**, limité dans l’**espace** et dans le **temps** : elle est plus facilement proportionnée."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le juge administratif doit statuer en **48 heures** : saisi lundi à 9 h, il se prononce au plus tard **mercredi à 9 h**."}]$ex$::jsonb),
  ('11f62154-d6e1-5fee-b539-bac2fad85fc5'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Un cortège, un préfet, un juge","competence":"argumenter","situation":"À Valbonne, des étudiants déclarent un défilé. Le préfet l’interdit ; les organisateurs saisissent le juge. Léna lit les deux textes et se demande où s’arrête le pouvoir de la police en temps normal et en temps d’exception.","documents":[{"id":"textes","type":"texte","genre":"source","titre":"L’arrêté, puis l’ordonnance du juge (résumés)","source":"Textes écrits pour l’exercice","blocs":["Arrêté du préfet : le défilé des étudiants est interdit samedi, au motif que le cortège risque de gêner la circulation du centre-ville.","Ordonnance du juge des référés : l’interdiction vise le défilé en entier, le préfet n’a pas examiné un autre parcours et ne cite aucun risque précis de trouble à l’ordre public. L’arrêté est suspendu."]},{"id":"frise","type":"frise","titre":"L’état d’urgence en France","source":"Dates tirées du cours","debut":1950,"fin":2020,"pas":10,"periodes":[{"id":"z1","debut":2015,"fin":2017,"nom":"Appliqué","teinte":"ambre"}],"evenements":[{"id":"z2","date":1955,"nom":"Loi de 1955"}]}],"questions":[{"enonce":"Touche le mot qui montre que le préfet invoque une simple gêne, et non un risque précis.","aide":"Le cours distingue le risque précis de trouble et la gêne.","type":"zone","document":"textes","multiple":false},{"enonce":"Quel critère du test de proportionnalité l’arrêté ne remplit-il pas, selon le juge ?","aide":"Le juge relève que le préfet n’a pas étudié d’autre parcours.","type":"choix","options":[{"id":"a","texte":"Aucun : l’arrêté a été suspendu sans aucune raison juridique"},{"id":"b","texte":"Adaptée : l’interdiction ne sert à aucun but d’intérêt général"},{"id":"c","texte":"Adaptée : la circulation n’a aucune importance pour la ville"},{"id":"d","texte":"Nécessaire : un autre parcours, moins sévère, aurait pu suffire"}],"multiple":false},{"enonce":"Combien d’années séparent la loi de 1955 du début de l’état d’urgence appliqué de 2015 à 2017 ?","aide":"Lis les dates sur la frise.","type":"nombre"},{"enonce":"Quel risque principal les régimes d’exception font-ils courir ?","aide":"Pense à ce qui reste après la fin de l’exception.","type":"choix","options":[{"id":"a","texte":"Que des mesures exceptionnelles passent peu à peu dans le droit commun"},{"id":"b","texte":"Que le juge administratif perde tous ses pouvoirs de contrôle"},{"id":"c","texte":"Que les manifestations deviennent obligatoires dans la ville"},{"id":"d","texte":"Que la Constitution soit supprimée au profit d’une loi unique"}],"multiple":false}]}$ex$::jsonb,
