  ('52823780-bb9b-56dd-b2e7-c6006a612e39'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Faut-il demander la permission pour publier ?","competence":"analyser-texte","situation":"Camille lance le journal de son lycée. Elle se demande si elle doit obtenir une autorisation avant chaque numéro et lit le texte de 1881 avec le tableau des deux types de contrôle.","documents":[{"id":"loi","type":"texte","genre":"source","titre":"Loi du 29 juillet 1881 sur la liberté de la presse","source":"Article 1er","blocs":["L’imprimerie et la librairie sont libres."]},{"id":"controle","type":"tableau","titre":"Deux manières de contrôler la presse","source":"Tableau tiré du cours","colonnes":["Contrôle","Principe"],"lignes":[["A priori","Autorisation préalable, censure administrative : supprimé"],["A posteriori","On répond devant un tribunal de ce qu’on a publié : régime actuel"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot par lequel la loi de 1881 pose le principe.","aide":"Le texte tient en une phrase : cherche l’adjectif.","type":"zone","document":"loi","multiple":false},{"enonce":"Camille doit-elle demander une autorisation avant de publier ?","aide":"Regarde la ligne « a priori » du tableau.","type":"choix","options":[{"id":"a","texte":"Non : on ne juge pas un journal avant sa parution, seulement après"},{"id":"b","texte":"Oui : un fonctionnaire doit relire chaque article avant parution"},{"id":"c","texte":"Oui : le préfet doit autoriser chaque numéro avant son impression"},{"id":"d","texte":"Non : un journal ne répond jamais de ce qu’il a écrit ni publié"}],"multiple":false},{"enonce":"Classe chaque situation dans le bon type de contrôle.","aide":"Le contrôle a priori a lieu avant la publication.","type":"categories","categories":[{"id":"c0","texte":"A priori (supprimé)"},{"id":"c1","texte":"A posteriori (actuel)"}],"items":[{"id":"i0","texte":"Un journal ne peut paraître sans autorisation préalable"},{"id":"i1","texte":"Un journaliste répond devant le juge de ce qu’il a écrit"},{"id":"i2","texte":"Un tribunal juge un article diffamatoire déjà publié"},{"id":"i3","texte":"Un fonctionnaire approuve chaque article avant la parution"}]}]}$ex$::jsonb,
