  ('52823780-bb9b-56dd-b2e7-c6006a612e39'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un petit média sous pression","competence":"argumenter","situation":"Le Courrier de Valbonne, journal local imaginaire, publie une enquête sur un marché public. Un juge demande au journaliste le nom de sa source ; en même temps, les plaintes s’accumulent. Dilan étudie le texte, puis le graphique.","documents":[{"id":"affaire","type":"texte","genre":"source","titre":"Une enquête et une demande du juge","source":"Texte écrit pour l’exercice","blocs":["Le Courrier de Valbonne publie une enquête sur un marché public attribué sans concurrence. Un juge demande au journaliste de révéler l’identité de sa source.","Le journaliste refuse en invoquant la protection de ses sources, inscrite dans la loi depuis 2010. Elle ne cède que devant un impératif prépondérant d’intérêt public."]},{"id":"plaintes","type":"graphique","forme":"barres","titre":"Plaintes contre le journal","source":"Données imaginées pour l’exercice","categories":["2021","2022","2023","2024"],"series":[{"nom":"Plaintes déposées","valeurs":[1,2,6,11],"teinte":"violet"},{"nom":"Condamnations obtenues","valeurs":[1,0,0,0],"teinte":"gris"}],"axeY":{"titre":"Nombre","unite":"par an","min":0,"max":12,"pas":2},"axeX":{"titre":"Année"},"valeurs":false}],"questions":[{"enonce":"Touche le mot qui nomme la garantie que le journaliste invoque.","aide":"C’est ce qui protège l’identité de qui lui a parlé.","type":"zone","document":"affaire","multiple":false},{"enonce":"Touche l’année où le journal subit le plus de plaintes.","aide":"Cherche la plus grande barre de la série des plaintes.","type":"zone","document":"plaintes","multiple":false},{"enonce":"Combien de plaintes ont été déposées contre le journal sur les quatre années ?","aide":"Additionne les barres de la série « Plaintes déposées ».","type":"nombre"},{"enonce":"Que suggère le profil de ce graphique ?","aide":"Compare les plaintes aux condamnations obtenues.","type":"choix","options":[{"id":"a","texte":"Que le journal publie de plus en plus de fausses nouvelles chaque année"},{"id":"b","texte":"Une procédure-bâillon possible : beaucoup de plaintes, peu de condamnations"},{"id":"c","texte":"Que toutes les plaintes déposées contre le journal étaient fondées"},{"id":"d","texte":"Que la loi de 1881 a été supprimée en 2022 par le Parlement français"}],"multiple":false},{"enonce":"Quand la protection des sources peut-elle céder ?","aide":"Relis la dernière phrase du texte.","type":"choix","options":[{"id":"a","texte":"Dès qu’un lecteur se plaint auprès de la rédaction du journal"},{"id":"b","texte":"Seulement devant un impératif prépondérant d’intérêt public"},{"id":"c","texte":"Jamais, quelles que soient les circonstances de l’enquête"},{"id":"d","texte":"Dès qu’un juge le souhaite, pour toute enquête en cours"}],"multiple":false}]}$ex$::jsonb,
