  ('9683105d-f114-5d2c-ade7-fa4371b506c0'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un article pour le journal du lycée","competence":"analyser-texte","situation":"Malo veut écrire un article dans le journal du lycée. Avant de commencer, il relit le texte de 1789 qui protège sa liberté, et ses limites.","documents":[{"id":"art11","type":"texte","genre":"source","titre":"Déclaration des droits de l’homme et du citoyen, 1789","source":"Article 11","blocs":["La libre communication des pensées et des opinions est un des droits les plus précieux de l’Homme : tout Citoyen peut donc parler, écrire, imprimer librement, sauf à répondre de l’abus de cette liberté dans les cas déterminés par la Loi."]}],"questions":[{"enonce":"Touche le mot qui désigne ce dont on peut avoir à répondre.","aide":"Le texte parle de ce qui dépasse l’usage normal de la liberté.","type":"zone","document":"art11","multiple":false},{"enonce":"Que signifie « répondre de l’abus de cette liberté » ?","aide":"Le texte renvoie à la loi.","type":"choix","options":[{"id":"a","texte":"Devoir demander l’accord du proviseur avant d’écrire"},{"id":"b","texte":"Pouvoir être poursuivi pour ce que la loi interdit"},{"id":"c","texte":"Renoncer à publier sous son nom"},{"id":"d","texte":"Ne jamais critiquer personne"}],"multiple":false},{"enonce":"Complète la phrase.","aide":"Le premier est celui que tu viens de lire.","type":"trous","segments":["La liberté d’expression est reconnue par l’article ",0," de la Déclaration de 1789 et par l’article ",1," de la Convention européenne des droits de l’homme."],"banque":["4","8","10","11","16"]}]}$ex$::jsonb,
