  ('9683105d-f114-5d2c-ade7-fa4371b506c0'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Débat ou délit ?","competence":"argumenter","situation":"Au CVL, six messages publiés en ligne ont été signalés. Zoé doit distinguer ce qui relève du débat de ce qui relève du délit, en s’appuyant sur la ligne de partage du cours.","documents":[{"id":"messages","type":"tableau","titre":"Six messages signalés","source":"Messages écrits pour l’exercice","colonnes":["Message","Contenu"],"lignes":[["A","Cette doctrine politique est absurde, et voici pourquoi."],["B","Ces gens sont des parasites à cause de leur religion."],["C","Un dessin se moque de la politique d’un ministre."],["D","Cette religion défend des idées que je trouve dépassées."],["E","Une camarade reçoit des menaces répétées, chaque soir."],["F","« Léa a volé le téléphone de Tom », écrit sans aucune preuve."]],"enteteLignes":true}],"questions":[{"enonce":"Touche les trois messages qui relèvent d’un délit.","aide":"Cherche ceux qui visent des personnes, pas une idée ni une institution.","type":"zone","document":"messages","multiple":true},{"enonce":"Associe chaque message à sa qualification.","aide":"Un groupe visé, des actes répétés, un fait précis sans preuve.","type":"association","gauche":[{"id":"g0","texte":"Message B"},{"id":"g1","texte":"Message E"},{"id":"g2","texte":"Message F"}],"droite":[{"id":"d0","texte":"Harcèlement et menaces"},{"id":"d1","texte":"Provocation à la haine"},{"id":"d2","texte":"Diffamation"}]},{"enonce":"Pourquoi les messages A, C et D relèvent-ils du débat ?","aide":"Regarde l’objet visé : idée, religion, institution ou personnes.","type":"choix","options":[{"id":"a","texte":"Ils ne sont lus par aucun autre élève de la classe"},{"id":"b","texte":"Ils visent des idées ou une institution, non des personnes"},{"id":"c","texte":"Ils sont tous publiés sans nom d’auteur sur le réseau"},{"id":"d","texte":"Ils sont toujours agréables à lire pour leurs lecteurs"}],"multiple":false},{"enonce":"Que protège la caricature du message C, selon la Cour européenne ?","aide":"La Cour a une formule constante en trois verbes.","type":"choix","options":[{"id":"a","texte":"Uniquement les idées qui plaisent à la majorité"},{"id":"b","texte":"Seulement les opinions de l’État"},{"id":"c","texte":"Les idées qui heurtent, choquent ou inquiètent"},{"id":"d","texte":"Aucune idée, dans aucun cas"}],"multiple":false}]}$ex$::jsonb,
