   $ex${"titre":"Sous pseudo, on ne risque rien ?","competence":"argumenter","situation":"Noé a publié un message public sous pseudonyme contre un camarade et croit ne rien risquer. Léo, du CVL, lui répond, puis rédige la charte du journal lycéen. Tu les aides à relire.","documents":[{"id":"sms","type":"dialogue","modele":"sms","source":"Messages écrits pour l’exercice","participants":[{"nom":"Noé","emoji":"🧑","cote":"gauche"},{"nom":"Léo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Noé","texte":"J’ai posté sous pseudo : comme je suis anonyme, je ne risque rien."},{"qui":"Léo","texte":"Ton message est public : c’est une publication. Et un pseudo n’empêche pas l’identification."}]},{"id":"charte","type":"fiche","modele":"affiche","entete":"Charte du journal lycéen","sousTitre":"Projet écrit pour l’exercice","emoji":"📰","lignes":[{"texte":"Les articles respectent le pluralisme et la neutralité du lycée","id":"z1"},{"texte":"Aucune injure ni diffamation","id":"z2"},{"texte":"Chaque article est signé de son auteur","id":"z3"},{"texte":"On peut critiquer une idée, jamais une personne pour ce qu’elle est","id":"z4"}]}],"questions":[{"enonce":"Touche le mot sur lequel repose l’erreur de Noé.","aide":"Il croit que cacher son nom l’abrite de toute poursuite.","type":"zone","document":"sms","multiple":false},{"enonce":"Pourquoi le message de Noé peut-il fonder des poursuites ?","aide":"Relis la réponse de Léo.","type":"choix","options":[{"id":"a","texte":"Parce que le lycée l’a interdit par un règlement intérieur"},{"id":"b","texte":"C’est une publication publique : on répond de ce qu’on publie"},{"id":"c","texte":"Parce qu’il a utilisé un pseudonyme plutôt que son vrai nom"},{"id":"d","texte":"Parce que seul un message privé peut fonder des poursuites"}],"multiple":false},{"enonce":"Touche la ligne de la charte qui reprend la ligne de partage entre débat et délit.","aide":"Cherche la phrase qui oppose « idée » et « personne ».","type":"zone","document":"charte","multiple":false},{"enonce":"Complète la phrase sur les lycéens.","aide":"Ce sont des représentants, une instance et une presse.","type":"trous","segments":["Au lycée, la liberté d’expression s’exerce notamment par les ",0,", le ",1," et les ",2," lycéens."],"banque":["délégués","journaux","CVL","préfets","jurés"]}]}$ex$::jsonb,
