ems":[{"id":"i0","texte":"La haine prospère sur le réseau"},{"id":"i1","texte":"Des contenus légaux retirés par précaution"},{"id":"i2","texte":"La désinformation circule sans frein"},{"id":"i3","texte":"Une plateforme menacée d’amende supprime dans le doute"}]},{"enonce":"Quelle est la question centrale de la régulation des réseaux sociaux ?","aide":"Pense aux règles privées, non votées, et à la voix de l’utilisateur.","type":"choix","options":[{"id":"a","texte":"Quel pays a inventé les tout premiers réseaux sociaux en ligne ?"},{"id":"b","texte":"Combien de personnes utilisent chaque jour un réseau social donné ?"},{"id":"c","texte":"Qui décide, selon quelles règles, et avec quel recours pour l’utilisateur ?"},{"id":"d","texte":"Quelle plateforme possède le plus d’images publiées par jour ?"}],"multiple":false}]}$ex$::jsonb,
