   $ex${"titre":"La Charte à l’épreuve des éco-délégués","competence":"analyser-texte","situation":"Les éco-délégués du lycée préparent un exposé sur la Charte de l’environnement. Ils lisent deux de ses articles et cherchent ce qu’ils disent, droits comme devoirs.","documents":[{"id":"charte","type":"texte","genre":"source","titre":"Charte de l’environnement","source":"Articles 1er et 2","blocs":["Article 1er. Chacun a le droit de vivre dans un environnement équilibré et respectueux de la santé.","Article 2. Toute personne a le devoir de prendre part à la préservation et à l’amélioration de l’environnement."]}],"questions":[{"enonce":"Touche le mot qui exprime une obligation pour chacun.","aide":"Cherche le mot opposé à « droit ».","type":"zone","document":"charte","multiple":false},{"enonce":"La Charte de l’environnement ne crée-t-elle que des droits ?","aide":"Compare les deux articles.","type":"choix","options":[{"id":"a","texte":"Non : elle crée aussi des devoirs"},{"id":"b","texte":"Oui : elle ne crée que des droits"},{"id":"c","texte":"Non : elle ne crée ni droits ni devoirs"},{"id":"d","texte":"Oui : elle ne crée que des devoirs"}],"multiple":false},{"enonce":"Depuis 2005, quelle valeur la Charte de l’environnement a-t-elle ?","aide":"Elle est adossée à la Constitution.","type":"choix","options":[{"id":"a","texte":"Celle d’un contrat passé entre plusieurs associations"},{"id":"b","texte":"Celle d’un simple règlement pris par le gouvernement"},{"id":"c","texte":"Celle d’un conseil consultatif sans portée juridique"},{"id":"d","texte":"Celle de la Déclaration de 1789 : une valeur constitutionnelle"}],"multiple":false}]}$ex$::jsonb,
