  ('fe688608-fb41-590d-80ef-5dbea17dfe23'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Quatre cas, quatre principes","competence":"raisonner","situation":"Le conseil municipal de Boisvert examine quatre dossiers d’environnement. Mina, éco-déléguée, doit dire à chaque fois quel principe de la Charte est à l’œuvre.","documents":[{"id":"cas","type":"tableau","titre":"Quatre dossiers","source":"Cas écrits pour l’exercice","colonnes":["Cas","Situation"],"lignes":[["1","Une usine rejette un produit dont la toxicité est établie : on lui impose des filtres avant tout dommage."],["2","Des scientifiques doutent qu’un pesticide nuise gravement et irréversiblement aux abeilles : on le suspend en attendant des études."],["3","Une entreprise responsable d’une marée noire paie le nettoyage des plages."],["4","Les habitants sont informés d’un projet de carrière et donnent leur avis avant la décision."]],"enteteLignes":true}],"questions":[{"enonce":"Associe chaque cas au principe qui s’applique.","aide":"Connu ou incertain ? Qui paie ? Qui est consulté ?","type":"association","gauche":[{"id":"g0","texte":"Cas 1"},{"id":"g1","texte":"Cas 2"},{"id":"g2","texte":"Cas 3"},{"id":"g3","texte":"Cas 4"}],"droite":[{"id":"d0","texte":"Pollueur-payeur"},{"id":"d1","texte":"Prévention"},{"id":"d2","texte":"Participation"},{"id":"d3","texte":"Précaution"}]},{"enonce":"Touche le cas où l’on agit sans attendre la certitude scientifique.","aide":"Cherche un doute des scientifiques sur un risque grave.","type":"zone","document":"cas","multiple":false},{"enonce":"Quelle différence y a-t-il entre prévention et précaution ?","aide":"Compare les cas 1 et 2.","type":"choix","options":[{"id":"a","texte":"Les deux désignent exactement la même chose"},{"id":"b","texte":"La prévention vise un risque connu, la précaution un risque encore incertain"},{"id":"c","texte":"La prévention vise un risque incertain, la précaution un risque connu"},{"id":"d","texte":"La prévention concerne les entreprises, la précaution les particuliers"}],"multiple":false},{"enonce":"Dans le cas 4, qu’apporte le principe de participation ?","aide":"Relis la situation du cas 4.","type":"choix","options":[{"id":"a","texte":"L’accès à l’information et la possibilité d’influencer les décisions"},{"id":"b","texte":"La réparation financière du dommage par le responsable"},{"id":"c","texte":"La suspension automatique du projet jusqu’à un nouveau vote"},{"id":"d","texte":"Le droit de décider seul à la place du préfet du département"}],"multiple":false}]}$ex$::jsonb,
