   $ex${"titre":"Défendre un bois : jusqu’où ?","competence":"argumenter","situation":"À Valmer, un bois doit laisser place à une carrière. Des habitants se mobilisent de plusieurs façons. Sacha examine les actions, puis les intérêts qui s’opposent, pour dire où passe la limite.","documents":[{"id":"actions","type":"tableau","titre":"Cinq actions","source":"Actions écrites pour l’exercice","colonnes":["N°","Action"],"lignes":[["1","Une pétition en ligne demande l’abandon du projet."],["2","Une manifestation est déclarée à la préfecture."],["3","Des militants dégradent une machine de chantier."],["4","Une association agréée attaque le permis devant le juge."],["5","Des militants occupent un bâtiment privé sans l’accord du propriétaire."]],"enteteLignes":true},{"id":"acteurs","type":"tableau","titre":"Les parties en présence","source":"Situation écrite pour l’exercice","colonnes":["Qui","Ce qu’il défend"],"lignes":[["Les ouvriers de la carrière","Leur emploi"],["Les riverains","La protection du bois"],["Le propriétaire du terrain","Son droit de disposer de son bien"],["La commune","Un équipement d’intérêt général"]],"enteteLignes":true}],"questions":[{"enonce":"Range chaque action selon qu’elle reste dans le cadre de la loi ou non.","aide":"La pétition, la manifestation et le recours en justice sont prévus par le droit.","type":"categories","categories":[{"id":"c0","texte":"Dans le cadre de la loi"},{"id":"c1","texte":"Au-delà de la loi"}],"items":[{"id":"i0","texte":"L’occupation d’un bâtiment privé sans accord"},{"id":"i1","texte":"Une pétition en ligne"},{"id":"i2","texte":"La dégradation d’une machine de chantier"},{"id":"i3","texte":"Une action en justice d’une association agréée"},{"id":"i4","texte":"Une manifestation déclarée"}]},{"enonce":"Touche les deux actions qui posent la question des limites de la désobéissance civile.","aide":"Cherche celles qui dépassent le cadre de la loi.","type":"zone","document":"actions","multiple":true},{"enonce":"Touche les deux parties dont l’opposition illustre « propriété contre intérêt général ».","aide":"Un droit individuel face à l’utilité collective.","type":"zone","document":"acteurs","multiple":true},{"enonce":"Une cause juste suffit-elle à justifier une action illégale ?","aide":"Relis la question de la désobéissance civile.","type":"choix","options":[{"id":"a","texte":"Non : agir pour une cause n’exonère pas du respect de la loi"},{"id":"b","texte":"Non : on ne peut rien faire pour défendre une cause"},{"id":"c","texte":"Oui : la cause défendue justifie tous les moyens employés"},{"id":"d","texte":"Oui : seulement si l’action est menée collectivement"}],"multiple":false}]}$ex$::jsonb,
